130	/**
131	 * Get the current authenticated user. Creates a DB record on first visit.
132	 * Returns null if not authenticated.
133	 */
134	export async function getAuthUser(): Promise<AuthContext | null> {
135	  // Check dev login cookie (gated on NODE_ENV + ENABLE_DEV_LOGIN, never Host)
136	  const devEmail = await getDevLoginEmail();
137	  if (devEmail) {
138	    return getDevUserByEmail(devEmail);
139	  }
140	
141	  if (!firebaseEnabled) {
142	    // Security F4: fail closed. A build/runtime missing
143	    // NEXT_PUBLIC_FIREBASE_API_KEY must never grant unauthenticated
144	    // global-admin access. The dev-user bypass is only permitted outside
145	    // production, and only when dev login is explicitly enabled.
146	    if (process.env.NODE_ENV === "production" || !isDevLoginEnabled()) {
147	      return null;
148	    }
149	    return getDevUser();
150	  }
151	
152	  // Verify session cookie (Firebase or WebAuthn)
153	  const sessionCookie = await getSessionCookie();
154	  if (!sessionCookie) return null;
155	
156	  try {
157	    let uid: string;
158	    let email: string;
159	    let displayName: string;
160	
161	    const hasServiceAccount = !!process.env.FIREBASE_SERVICE_ACCOUNT_KEY;
162	
163	    if (sessionCookie.startsWith("webauthn.")) {
164	      // WebAuthn/OTP session. Signature verification is unconditional
165	      // (Security F1) — it must never be skippable via an unrelated env
166	      // var (previously gated on `hasServiceAccount`). A missing
167	      // SESSION_SIGNING_SECRET throws inside getSessionSigningSecret()
168	      // (called from verifyWebauthnSessionCookie), which is caught below
169	      // and treated as unauthenticated: fail closed.
170	      const verified = verifyWebauthnSessionCookie(sessionCookie);
171	      if (!verified) return null;
172	
173	      uid = verified.uid;
174	      email = verified.email;
175	      displayName = "";
176	    } else if (hasServiceAccount) {
177	      // Production: verify Firebase session cookie
178	      const { getAdminAuth } = await import("@/lib/firebase-admin");
179	      const adminAuth = getAdminAuth();
180	      const decoded = await adminAuth.verifySessionCookie(sessionCookie, true);
181	      uid = decoded.uid;
182	      email = (decoded.email ?? "").toLowerCase().trim();
183	      displayName = decoded.name ?? "";
184	    } else if (process.env.NODE_ENV !== "production") {
185	      // Dev only: decode the ID token JWT payload without verification.
186	      // Guarded on NODE_ENV so a production deploy that is missing
187	      // FIREBASE_SERVICE_ACCOUNT_KEY cannot fall back to trusting an
188	      // unverified client-supplied token (same fail-closed principle as F4).
189	      const parts = sessionCookie.split(".");
190	      if (parts.length !== 3) return null;
191	      const payload = JSON.parse(Buffer.from(parts[1], "base64url").toString());
192	      uid = payload.user_id ?? payload.sub ?? "";
193	      email = (payload.email ?? "").toLowerCase().trim();
194	      displayName = payload.name ?? "";
195	    } else {
196	      // Production with no service account and no recognised session
197	      // format: fail closed rather than trusting an unverified token.
198	      return null;
199	    }
200	
201	    if (!uid) return null;
202	
203	    // Find or create user
204	    let [dbUser] = await db
205	      .select()
206	      .from(users)
207	      .where(eq(users.firebaseUid, uid))
208	      .limit(1);
209	
210	    if (!dbUser && email) {
211	      // Check by email in case user was created before signing up
212	      [dbUser] = await db
213	        .select()
214	        .from(users)
215	        .where(eq(users.email, email))
216	        .limit(1);
217	
218	      if (dbUser) {
219	        // Link existing user to Firebase account
220	        [dbUser] = await db
221	          .update(users)
222	          .set({
223	            firebaseUid: uid,
224	            firstName: displayName.split(" ")[0] || dbUser.firstName,
225	            lastName: displayName.split(" ").slice(1).join(" ") || dbUser.lastName,
226	          })
227	          .where(eq(users.id, dbUser.id))
228	          .returning();
229	      } else {
230	        // Create new user
231	        const nameParts = displayName.split(" ");
232	        [dbUser] = await db
233	          .insert(users)
234	          .values({
235	            firebaseUid: uid,
236	            email,
237	            firstName: nameParts[0] || "",
238	            lastName: nameParts.slice(1).join(" ") || "",
239	            phone: null,
240	          })
241	          .onConflictDoUpdate({
242	            target: users.firebaseUid,
243	            set: { email, updatedAt: new Date() },
244	          })
245	          .returning();
246	      }
247	    }
248	
249	    if (!dbUser) return null;
250	
251	    // Link orphaned requests by email
252	    const linkedRequests = await db
253	      .update(fobRequests)
254	      .set({ requesterId: dbUser.id })
255	      .where(
256	        and(
257	          eq(fobRequests.orphanEmail, dbUser.email),
258	          isNull(fobRequests.requesterId)
259	        )
260	      )
261	      .returning({ orphanFirstName: fobRequests.orphanFirstName, orphanLastName: fobRequests.orphanLastName });
262	
263	    // If user has no name, populate from orphan request details
264	    if (!dbUser.firstName && !dbUser.lastName && linkedRequests.length > 0) {
265	      const orphan = linkedRequests.find((r) => r.orphanFirstName || r.orphanLastName);
266	      if (orphan) {
267	        [dbUser] = await db
268	          .update(users)
269	          .set({
270	            firstName: orphan.orphanFirstName ?? "",
271	            lastName: orphan.orphanLastName ?? "",
272	          })
273	          .where(eq(users.id, dbUser.id))
274	          .returning();
275	      }
276	    }
277	
278	    // Fetch memberships
279	    return buildAuthContext(dbUser);
280	  } catch (err) {
281	    console.error("Session verification failed:", err);
282	    return null;
283	  }
284	}
