322	async function getSessionCookie(): Promise<string | null> {
323	  try {
324	    const { cookies } = await import("next/headers");
325	    const cookieStore = await cookies();
326	    return cookieStore.get("session")?.value ?? null;
327	  } catch {
328	    return null;
329	  }
330	}
