332	/**
333	 * Single source of truth for whether dev-only auth bypasses (dev-login
334	 * cookie, dev-user fallback) may run at all.
335	 *
336	 * Security F2: previously gated on the client-controlled `Host` header
337	 * (`host.includes("localhost")`). A GCP HTTPS load balancer that forwards a
338	 * spoofed `Host: localhost` to the container turned that into a one-request,
339	 * no-secret-required global-admin takeover. Never gate on Host again.
340	 *
341	 * Now gated on NODE_ENV plus an explicit opt-in flag, so it is off by
342	 * default everywhere and cannot be turned on in production at all.
343	 */
344	export function isDevLoginEnabled(): boolean {
345	  return process.env.NODE_ENV !== "production" && process.env.ENABLE_DEV_LOGIN === "true";
346	}
347	
348	async function getDevLoginEmail(): Promise<string | null> {
349	  if (!isDevLoginEnabled()) return null;
350	  try {
351	    const { cookies } = await import("next/headers");
352	    const cookieStore = await cookies();
353	    return cookieStore.get("dev_login_email")?.value ?? null;
354	  } catch {
355	    return null;
356	  }
357	}
