359	async function getDevUserByEmail(email: string): Promise<AuthContext | null> {
360	  const [dbUser] = await db
361	    .select()
362	    .from(users)
363	    .where(eq(users.email, email))
364	    .limit(1);
365	
366	  if (!dbUser) return null;
367	  return buildAuthContext(dbUser);
368	}
369	
370	async function getDevUser(): Promise<AuthContext> {
371	  const DEV_FIREBASE_UID = "dev_user_local";
372	
373	  let [dbUser] = await db
374	    .select()
375	    .from(users)
376	    .where(eq(users.firebaseUid, DEV_FIREBASE_UID))
377	    .limit(1);
378	
379	  if (!dbUser) {
380	    [dbUser] = await db
381	      .insert(users)
382	      .values({
383	        firebaseUid: DEV_FIREBASE_UID,
384	        email: "dev@accessbuddy.local",
385	        firstName: "Dev",
386	        lastName: "Admin",
387	        phone: null,
388	      })
389	      .returning();
390	
391	    const allTenants = await db.select({ id: tenants.id }).from(tenants);
392	    for (const t of allTenants) {
393	      await db.insert(tenantMemberships).values({
394	        tenantId: t.id,
395	        userId: dbUser.id,
396	        membershipCategory: "Developer",
397	        status: "active",
398	        currentSeason: "2025/2026",
399	      });
400	      await db.insert(adminAssignments).values({
401	        tenantId: t.id,
402	        userId: dbUser.id,
403	        roleType: AdminRoleType.GLOBAL_ADMIN,
404	        permissions: [],
405	      });
406	    }
407	  }
408	
409	  return buildAuthContext(dbUser);
410	}
