import { createHmac, timingSafeEqual } from "node:crypto";
import { db } from "@accessbuddy/db";
import { users, tenantMemberships, adminAssignments, tenants, fobRequests } from "@accessbuddy/db";
import { eq, and, isNull } from "drizzle-orm";
import { AdminRoleType } from "@accessbuddy/shared";
import { getSessionSigningSecret } from "@/env";

/** Shared session lifetime for WebAuthn/OTP-signed session cookies. */
export const SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 14; // 14 days

export type WebauthnSessionPayload = {
  uid: string;
  email: string;
  iat: number;
  exp: number;
  webauthn: true;
};

/**
 * Sign a WebAuthn/OTP session payload with the dedicated
 * SESSION_SIGNING_SECRET (Security F1). Never falls back to a hardcoded
 * literal or CRON_SECRET: getSessionSigningSecret() throws if the secret is
 * unset, so callers fail closed rather than issuing an unsigned or
 * trivially-forgeable cookie. Used by the OTP verify route; the WebAuthn
 * login route (apps/web/src/app/api/auth/webauthn/login/route.ts, not owned
 * by this change) still signs independently with the old
 * `CRON_SECRET ?? "webauthn-session-secret"` pattern and needs to be
 * switched to this helper — see the handoff note in the auth-hardening
 * report.
 */
export function signWebauthnSession(
  payload: Pick<WebauthnSessionPayload, "uid" | "email">
): string {
  const fullPayload: WebauthnSessionPayload = {
    uid: payload.uid,
    email: payload.email,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + SESSION_MAX_AGE_SECONDS,
    webauthn: true,
  };
  const payloadStr = JSON.stringify(fullPayload);
  const secret = getSessionSigningSecret();
  const sig = createHmac("sha256", secret).update(payloadStr).digest("base64url");
  return `webauthn.${Buffer.from(payloadStr).toString("base64url")}.${sig}`;
}

export type VerifiedWebauthnSession = { uid: string; email: string };

/**
 * Verify a `webauthn.<payload>.<sig>` session cookie value and return its
 * `{ uid, email }`, or `null` if the signature is missing, forged,
 * malformed, or the token is expired.
 *
 * Extracted from getAuthUser as a standalone pure(ish) function so it is
 * unit-testable without a Next.js request context (next/headers' cookies()
 * throws outside one). Signature and expiry verification are unconditional
 * (Security F1) — there is no code path here that skips them.
 */
export function verifyWebauthnSessionCookie(cookieValue: string): VerifiedWebauthnSession | null {
  const parts = cookieValue.split(".");
  if (parts.length !== 3 || parts[0] !== "webauthn") return null;

  const payloadStr = Buffer.from(parts[1], "base64url").toString();
  let payload: Record<string, unknown>;
  try {
    payload = JSON.parse(payloadStr);
  } catch {
    return null;
  }

  // getSessionSigningSecret() throws if SESSION_SIGNING_SECRET is unset or
  // too short — never fall back to a literal or to CRON_SECRET. Callers
  // (getAuthUser) catch this and treat it as unauthenticated: fail closed.
  const secret = getSessionSigningSecret();
  const expectedSig = createHmac("sha256", secret).update(payloadStr).digest("base64url");
  const providedSig = parts[2];
  const sigValid =
    providedSig.length === expectedSig.length &&
    timingSafeEqual(Buffer.from(providedSig), Buffer.from(expectedSig));
  if (!sigValid) return null;

  const exp = typeof payload.exp === "number" ? payload.exp : null;
  if (!exp || exp < Math.floor(Date.now() / 1000)) return null;

  const uid =
    (typeof payload.uid === "string" && payload.uid) ||
    (typeof payload.sub === "string" && payload.sub) ||
    "";
  if (!uid) return null;
  const email = typeof payload.email === "string" ? payload.email.toLowerCase().trim() : "";

  return { uid, email };
}

export type AuthUser = {
  id: string;
  firebaseUid: string;
  email: string;
  firstName: string;
  lastName: string;
  phone: string | null;
};

export type TenantMembership = {
  tenantId: string;
  membershipCategory: string | null;
  status: string;
  role: {
    roleType: string;
    permissions: string[];
  } | null;
};

export type AuthContext = {
  user: AuthUser;
  memberships: TenantMembership[];
};

/**
 * Check if the authenticated user has global admin privileges.
 */
export function isGlobalAdmin(auth: AuthContext | null): boolean {
  return auth?.memberships.some(
    (m) => m.role?.roleType === AdminRoleType.GLOBAL_ADMIN
  ) ?? false;
}

const firebaseEnabled = !!process.env.NEXT_PUBLIC_FIREBASE_API_KEY;

/**
 * Get the current authenticated user. Creates a DB record on first visit.
 * Returns null if not authenticated.
 */
export async function getAuthUser(): Promise<AuthContext | null> {
  // Check dev login cookie (gated on NODE_ENV + ENABLE_DEV_LOGIN, never Host)
  const devEmail = await getDevLoginEmail();
  if (devEmail) {
    return getDevUserByEmail(devEmail);
  }

  if (!firebaseEnabled) {
    // Security F4: fail closed. A build/runtime missing
    // NEXT_PUBLIC_FIREBASE_API_KEY must never grant unauthenticated
    // global-admin access. The dev-user bypass is only permitted outside
    // production, and only when dev login is explicitly enabled.
    if (process.env.NODE_ENV === "production" || !isDevLoginEnabled()) {
      return null;
    }
    return getDevUser();
  }

  // Verify session cookie (Firebase or WebAuthn)
  const sessionCookie = await getSessionCookie();
  if (!sessionCookie) return null;

  try {
    let uid: string;
    let email: string;
    let displayName: string;

    const hasServiceAccount = !!process.env.FIREBASE_SERVICE_ACCOUNT_KEY;

    if (sessionCookie.startsWith("webauthn.")) {
      // WebAuthn/OTP session. Signature verification is unconditional
      // (Security F1) — it must never be skippable via an unrelated env
      // var (previously gated on `hasServiceAccount`). A missing
      // SESSION_SIGNING_SECRET throws inside getSessionSigningSecret()
      // (called from verifyWebauthnSessionCookie), which is caught below
      // and treated as unauthenticated: fail closed.
      const verified = verifyWebauthnSessionCookie(sessionCookie);
      if (!verified) return null;

      uid = verified.uid;
      email = verified.email;
      displayName = "";
    } else if (hasServiceAccount) {
      // Production: verify Firebase session cookie
      const { getAdminAuth } = await import("@/lib/firebase-admin");
      const adminAuth = getAdminAuth();
      const decoded = await adminAuth.verifySessionCookie(sessionCookie, true);
      uid = decoded.uid;
      email = (decoded.email ?? "").toLowerCase().trim();
      displayName = decoded.name ?? "";
    } else if (process.env.NODE_ENV !== "production") {
      // Dev only: decode the ID token JWT payload without verification.
      // Guarded on NODE_ENV so a production deploy that is missing
      // FIREBASE_SERVICE_ACCOUNT_KEY cannot fall back to trusting an
      // unverified client-supplied token (same fail-closed principle as F4).
      const parts = sessionCookie.split(".");
      if (parts.length !== 3) return null;
      const payload = JSON.parse(Buffer.from(parts[1], "base64url").toString());
      uid = payload.user_id ?? payload.sub ?? "";
      email = (payload.email ?? "").toLowerCase().trim();
      displayName = payload.name ?? "";
    } else {
      // Production with no service account and no recognised session
      // format: fail closed rather than trusting an unverified token.
      return null;
    }

    if (!uid) return null;

    // Find or create user
    let [dbUser] = await db
      .select()
      .from(users)
      .where(eq(users.firebaseUid, uid))
      .limit(1);

    if (!dbUser && email) {
      // Check by email in case user was created before signing up
      [dbUser] = await db
        .select()
        .from(users)
        .where(eq(users.email, email))
        .limit(1);

      if (dbUser) {
        // Link existing user to Firebase account
        [dbUser] = await db
          .update(users)
          .set({
            firebaseUid: uid,
            firstName: displayName.split(" ")[0] || dbUser.firstName,
            lastName: displayName.split(" ").slice(1).join(" ") || dbUser.lastName,
          })
          .where(eq(users.id, dbUser.id))
          .returning();
      } else {
        // Create new user
        const nameParts = displayName.split(" ");
        [dbUser] = await db
          .insert(users)
          .values({
            firebaseUid: uid,
            email,
            firstName: nameParts[0] || "",
            lastName: nameParts.slice(1).join(" ") || "",
            phone: null,
          })
          .onConflictDoUpdate({
            target: users.firebaseUid,
            set: { email, updatedAt: new Date() },
          })
          .returning();
      }
    }

    if (!dbUser) return null;

    // Link orphaned requests by email
    const linkedRequests = await db
      .update(fobRequests)
      .set({ requesterId: dbUser.id })
      .where(
        and(
          eq(fobRequests.orphanEmail, dbUser.email),
          isNull(fobRequests.requesterId)
        )
      )
      .returning({ orphanFirstName: fobRequests.orphanFirstName, orphanLastName: fobRequests.orphanLastName });

    // If user has no name, populate from orphan request details
    if (!dbUser.firstName && !dbUser.lastName && linkedRequests.length > 0) {
      const orphan = linkedRequests.find((r) => r.orphanFirstName || r.orphanLastName);
      if (orphan) {
        [dbUser] = await db
          .update(users)
          .set({
            firstName: orphan.orphanFirstName ?? "",
            lastName: orphan.orphanLastName ?? "",
          })
          .where(eq(users.id, dbUser.id))
          .returning();
      }
    }

    // Fetch memberships
    return buildAuthContext(dbUser);
  } catch (err) {
    console.error("Session verification failed:", err);
    return null;
  }
}

async function buildAuthContext(dbUser: typeof users.$inferSelect): Promise<AuthContext> {
  const memberships = await db
    .select({
      tenantId: tenantMemberships.tenantId,
      membershipCategory: tenantMemberships.membershipCategory,
      status: tenantMemberships.status,
      roleType: adminAssignments.roleType,
      permissions: adminAssignments.permissions,
    })
    .from(tenantMemberships)
    .leftJoin(
      adminAssignments,
      eq(tenantMemberships.userId, adminAssignments.userId)
    )
    .where(eq(tenantMemberships.userId, dbUser.id));

  return {
    user: {
      id: dbUser.id,
      firebaseUid: dbUser.firebaseUid,
      email: dbUser.email,
      firstName: dbUser.firstName,
      lastName: dbUser.lastName,
      phone: dbUser.phone,
    },
    memberships: memberships.map((m) => ({
      tenantId: m.tenantId,
      membershipCategory: m.membershipCategory,
      status: m.status,
      role: m.roleType
        ? { roleType: m.roleType, permissions: m.permissions ?? [] }
        : null,
    })),
  };
}

async function getSessionCookie(): Promise<string | null> {
  try {
    const { cookies } = await import("next/headers");
    const cookieStore = await cookies();
    return cookieStore.get("session")?.value ?? null;
  } catch {
    return null;
  }
}

/**
 * Single source of truth for whether dev-only auth bypasses (dev-login
 * cookie, dev-user fallback) may run at all.
 *
 * Security F2: previously gated on the client-controlled `Host` header
 * (`host.includes("localhost")`). A GCP HTTPS load balancer that forwards a
 * spoofed `Host: localhost` to the container turned that into a one-request,
 * no-secret-required global-admin takeover. Never gate on Host again.
 *
 * Now gated on NODE_ENV plus an explicit opt-in flag, so it is off by
 * default everywhere and cannot be turned on in production at all.
 */
export function isDevLoginEnabled(): boolean {
  return process.env.NODE_ENV !== "production" && process.env.ENABLE_DEV_LOGIN === "true";
}

async function getDevLoginEmail(): Promise<string | null> {
  if (!isDevLoginEnabled()) return null;
  try {
    const { cookies } = await import("next/headers");
    const cookieStore = await cookies();
    return cookieStore.get("dev_login_email")?.value ?? null;
  } catch {
    return null;
  }
}

async function getDevUserByEmail(email: string): Promise<AuthContext | null> {
  const [dbUser] = await db
    .select()
    .from(users)
    .where(eq(users.email, email))
    .limit(1);

  if (!dbUser) return null;
  return buildAuthContext(dbUser);
}

async function getDevUser(): Promise<AuthContext> {
  const DEV_FIREBASE_UID = "dev_user_local";

  let [dbUser] = await db
    .select()
    .from(users)
    .where(eq(users.firebaseUid, DEV_FIREBASE_UID))
    .limit(1);

  if (!dbUser) {
    [dbUser] = await db
      .insert(users)
      .values({
        firebaseUid: DEV_FIREBASE_UID,
        email: "dev@accessbuddy.local",
        firstName: "Dev",
        lastName: "Admin",
        phone: null,
      })
      .returning();

    const allTenants = await db.select({ id: tenants.id }).from(tenants);
    for (const t of allTenants) {
      await db.insert(tenantMemberships).values({
        tenantId: t.id,
        userId: dbUser.id,
        membershipCategory: "Developer",
        status: "active",
        currentSeason: "2025/2026",
      });
      await db.insert(adminAssignments).values({
        tenantId: t.id,
        userId: dbUser.id,
        roleType: AdminRoleType.GLOBAL_ADMIN,
        permissions: [],
      });
    }
  }

  return buildAuthContext(dbUser);
}

