1	import { NextRequest, NextResponse } from "next/server";
2	import { cookies } from "next/headers";
3	import { AuditEntityType, AuditAction } from "@accessbuddy/shared";
4	
5	const SESSION_COOKIE_NAME = "session";
6	const SESSION_MAX_AGE = 60 * 60 * 24 * 14; // 14 days
7	
8	export async function POST(request: NextRequest) {
9	  try {
10	    const { idToken } = await request.json();
11	    if (!idToken) {
12	      return NextResponse.json({ error: "Token required" }, { status: 400 });
13	    }
14	
15	    const hasServiceAccount = !!process.env.FIREBASE_SERVICE_ACCOUNT_KEY;
16	
17	    let sessionValue: string;
18	
19	    if (hasServiceAccount) {
20	      // Production: create a proper session cookie via Firebase Admin
21	      const { getAdminAuth } = await import("@/lib/firebase-admin");
22	      const adminAuth = getAdminAuth();
23	      sessionValue = await adminAuth.createSessionCookie(idToken, {
24	        expiresIn: SESSION_MAX_AGE * 1000,
25	      });
26	    } else {
27	      // Dev: store the ID token directly as the session cookie
28	      sessionValue = idToken;
29	    }
30	
31	    const cookieStore = await cookies();
32	    cookieStore.set(SESSION_COOKIE_NAME, sessionValue, {
33	      httpOnly: true,
34	      secure: process.env.NODE_ENV === "production",
35	      sameSite: "lax",
36	      path: "/",
37	      maxAge: SESSION_MAX_AGE,
38	    });
39	
40	    // Build redirect hints: check admin assignments and memberships
41	    let isAdmin = false;
42	    let tenantSlug: string | null = null;
43	    let membershipCount = 0;
44	    try {
45	      const { db } = await import("@accessbuddy/db");
46	      const { users, adminAssignments, tenants, tenantMemberships } = await import("@accessbuddy/db");
47	      const { eq } = await import("drizzle-orm");
48	
49	      // Decode the token to get the email
50	      let email: string | null = null;
51	      if (hasServiceAccount) {
52	        const { getAdminAuth } = await import("@/lib/firebase-admin");
53	        const decoded = await getAdminAuth().verifyIdToken(idToken);
54	        email = decoded.email ?? null;
55	      } else {
56	        // Dev mode: decode JWT payload
57	        const payload = JSON.parse(Buffer.from(idToken.split(".")[1], "base64").toString());
58	        email = payload.email ?? null;
59	      }
60	
61	      if (email) {
62	        const [user] = await db.select({ id: users.id }).from(users).where(eq(users.email, email)).limit(1);
63	        if (user) {
64	          // Check admin assignments first (admin wins)
65	          let adminTenantId: string | null = null;
66	          const [admin] = await db
67	            .select({ tenantId: adminAssignments.tenantId })
68	            .from(adminAssignments)
69	            .where(eq(adminAssignments.userId, user.id))
70	            .limit(1);
71	          if (admin && admin.tenantId) {
72	            adminTenantId = admin.tenantId;
73	            const [t] = await db.select({ slug: tenants.slug }).from(tenants).where(eq(tenants.id, admin.tenantId)).limit(1);
74	            if (t) {
75	              isAdmin = true;
76	              tenantSlug = t.slug;
77	            }
78	          } else if (admin && !admin.tenantId) {
79	            // Global admin - find first tenant
80	            const [t] = await db.select({ id: tenants.id, slug: tenants.slug }).from(tenants).limit(1);
81	            if (t) {
82	              isAdmin = true;
83	              tenantSlug = t.slug;
84	              adminTenantId = t.id;
85	            }
86	          }
87	
88	          // Check memberships for non-admin routing
89	          const memberships = await db
90	            .select({ tenantId: tenantMemberships.tenantId })
91	            .from(tenantMemberships)
92	            .where(eq(tenantMemberships.userId, user.id));
93	          membershipCount = memberships.length;
94	
95	          // If not admin but has memberships, set tenantSlug for routing
96	          if (!isAdmin && membershipCount > 0) {
97	            const [t] = await db
98	              .select({ slug: tenants.slug })
99	              .from(tenants)
100	              .where(eq(tenants.id, memberships[0].tenantId))
101	              .limit(1);
102	            if (t) tenantSlug = t.slug;
103	          }
104	
105	          // Record login in audit log (fire-and-forget, don't block login)
106	          const { getClientIp } = await import("@/lib/rate-limit");
107	          const { createAuditEntry } = await import("@/lib/services/audit");
108	          const ip = getClientIp(request);
109	          createAuditEntry(db, {
110	            tenantId: adminTenantId ?? memberships[0]?.tenantId ?? null,
111	            entityType: AuditEntityType.MEMBER,
112	            entityId: user.id,
113	            action: AuditAction.LOGIN,
114	            actorId: user.id,
115	            actorType: "user",
116	            metadata: { email },
117	            ipAddress: ip === "unknown" ? null : ip,
118	          }).catch(() => {});
119	        }
120	      }
121	    } catch {
122	      // Non-critical - just won't auto-route
123	    }
124	
125	    return NextResponse.json({ success: true, isAdmin, tenantSlug, membershipCount });
126	  } catch (err) {
127	    console.error("Session creation error:", err);
128	    return NextResponse.json({ error: "Failed to create session" }, { status: 401 });
129	  }
130	}
131	
132	export async function DELETE() {
133	  const cookieStore = await cookies();
134	  cookieStore.delete(SESSION_COOKIE_NAME);
135	  return NextResponse.json({ success: true });
136	}
