1	/**
2	 * Postgres-backed fixed-window rate limiter (`rate_limit_buckets`).
3	 *
4	 * Replaces the previous module-level in-memory Map, which was per-instance:
5	 * on Cloud Run scale-out the effective ceiling multiplied by instance count,
6	 * and cold starts reset counters to zero. Every check now goes through one
7	 * atomic `INSERT ... ON CONFLICT` so concurrent requests across any number
8	 * of instances see a single, consistent counter.
9	 *
10	 * Kill switch: set `RATE_LIMIT_DISABLED=1` in the environment to bypass all
11	 * checks. Use this as a break-glass if the limiter misbehaves.
12	 *
13	 * NOT tenant-scoped: bucket keys are caller-defined strings (IP, email,
14	 * namespace) evaluated pre-auth. See the note in
15	 * packages/db/src/schema/auth-tokens.ts — this table must not get RLS
16	 * tenant policies.
17	 */
18	
19	import { db } from "@accessbuddy/db";
20	import { rateLimitBuckets } from "@accessbuddy/db/src/schema/auth-tokens";
21	import { sql } from "drizzle-orm";
22	
23	/**
24	 * Extract the client IP from the request headers. Cloud Run forwards the
25	 * original client IP in `x-forwarded-for` as a comma-separated list where
26	 * the first entry is the origin client.
27	 *
28	 * Returns `"unknown"` when no IP can be determined — those requests share a
29	 * single bucket, which is the strictest possible treatment.
30	 */
31	export function getClientIp(request: Request): string {
32	  const forwardedFor = request.headers.get("x-forwarded-for");
33	  if (forwardedFor) {
34	    const first = forwardedFor.split(",")[0]?.trim();
35	    if (first) return first;
36	  }
37	  const realIp = request.headers.get("x-real-ip");
38	  if (realIp) return realIp.trim();
39	  return "unknown";
40	}
41	
42	export type RateLimitResult = {
43	  ok: boolean;
44	  remaining: number;
45	  /** Seconds until the current window resets. */
46	  retryAfter: number;
47	};
48	
49	export type RateLimitOptions = {
50	  /** Logical bucket name — use one per endpoint. */
51	  namespace: string;
52	  /** Window duration in seconds. */
53	  windowSeconds: number;
54	  /** Maximum requests allowed per key within the window. */
55	  max: number;
56	};
57	
58	/**
59	 * Increment and check the counter for `key` inside `namespace`. Returns a
60	 * result object describing whether the request should be allowed, how many
61	 * requests remain in the current window, and how long until the window
62	 * resets.
63	 *
64	 * The increment-and-check is a single atomic upsert: on conflict, the row is
65	 * reset to count=1 if the previous window has expired, otherwise the count
66	 * is incremented. This is race-safe under concurrent requests without a
67	 * separate lock.
68	 *
69	 * Respects the `RATE_LIMIT_DISABLED=1` environment variable kill switch.
70	 */
71	export async function checkRateLimit(
72	  key: string,
73	  options: RateLimitOptions
74	): Promise<RateLimitResult> {
75	  if (process.env.RATE_LIMIT_DISABLED === "1") {
76	    return { ok: true, remaining: options.max, retryAfter: 0 };
77	  }
78	
79	  const bucketKey = `${options.namespace}:${key}`;
80	
81	  // All time arithmetic runs server-side with now(), for two reasons: (1)
82	  // interpolating a JS Date into the raw sql template throws under the
83	  // postgres.js driver ("string argument ... Received an instance of Date"),
84	  // and (2) using the database clock removes app/DB clock-skew from the
85	  // window comparison. Only windowSeconds (a number) is bound as a parameter.
86	  const windowSeconds = options.windowSeconds;
87	
88	  const rows = await db.execute<{ count: number; reset_at: string | Date }>(sql`
89	    INSERT INTO ${rateLimitBuckets} (key, count, reset_at)
90	    VALUES (${bucketKey}, 1, now() + make_interval(secs => ${windowSeconds}))
91	    ON CONFLICT (key) DO UPDATE SET
92	      count = CASE
93	        WHEN ${rateLimitBuckets.resetAt} <= now() THEN 1
94	        ELSE ${rateLimitBuckets.count} + 1
95	      END,
96	      reset_at = CASE
97	        WHEN ${rateLimitBuckets.resetAt} <= now() THEN now() + make_interval(secs => ${windowSeconds})
98	        ELSE ${rateLimitBuckets.resetAt}
99	      END
100	    RETURNING count, reset_at
101	  `);
102	
103	  const row = rows[0];
104	  if (!row) {
105	    // Should never happen (INSERT ... RETURNING always returns a row), but
106	    // fail open-with-logging rather than throw on an auth send path.
107	    console.error("[rate-limit] upsert returned no row for", bucketKey);
108	    return { ok: true, remaining: options.max - 1, retryAfter: 0 };
109	  }
110	
111	  const resetAt = new Date(row.reset_at);
112	  const count = Number(row.count);
113	
114	  if (count > options.max) {
115	    return {
116	      ok: false,
117	      remaining: 0,
118	      retryAfter: Math.max(1, Math.ceil((resetAt.getTime() - Date.now()) / 1000)),
119	    };
120	  }
121	
122	  return {
123	    ok: true,
124	    remaining: Math.max(0, options.max - count),
125	    retryAfter: 0,
126	  };
127	}
128	
129	/**
130	 * Convenience wrapper: enforce independent rate limits keyed on both the
131	 * client IP and the target email, so an attacker cannot dodge the IP bucket
132	 * by rotating source addresses, nor dodge the email bucket by spraying many
133	 * targets from one IP. Returns the first failing result, or the IP result
134	 * if both pass.
135	 */
136	export async function checkRateLimitIpAndEmail(
137	  namespace: string,
138	  ip: string,
139	  email: string,
140	  options: { windowSeconds: number; maxPerIp: number; maxPerEmail: number }
141	): Promise<RateLimitResult> {
142	  const ipResult = await checkRateLimit(`ip:${ip}`, {
143	    namespace,
