149	  const emailResult = await checkRateLimit(`email:${email}`, {
150	    namespace,
151	    windowSeconds: options.windowSeconds,
152	    max: options.maxPerEmail,
153	  });
154	  return emailResult;
155	}
156	
157	/** Test-only: clear all buckets. Not exported through the barrel. */
158	export async function __resetRateLimitStores(): Promise<void> {
159	  await db.delete(rateLimitBuckets);
160	}
