import { NextRequest, NextResponse } from "next/server";
import { eq } from "drizzle-orm";
import { db, users, tenants } from "@accessbuddy/db";
import { AuditEntityType } from "@accessbuddy/shared";
import { setOtp } from "@/lib/otp-store";
import { checkRateLimitIpAndEmail, getClientIp } from "@/lib/rate-limit";
import { withTenant } from "@/lib/with-tenant";
import { z } from "zod";

const schema = z.object({ email: z.string().email() });

/**
 * Platform-level OTP send. Used by the PWA sign-in flow where magic links
 * can't transfer session cookies to the standalone app context.
 *
 * Security hardening (2026-07 review): the dev-code disclosure and rate
 * limiting are now gated on NODE_ENV, never on the client-controlled Host
 * header (F2/F3) — see lib/auth.ts's isDevLoginEnabled() note for the
 * Host-header exploit this class of check used to allow.
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const parsed = schema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json({ error: "Valid email required" }, { status: 400 });
    }

    const email = parsed.data.email.toLowerCase().trim();
    const ip = getClientIp(request);

    const rl = await checkRateLimitIpAndEmail("auth.send-otp", ip, email, {
      windowSeconds: 60,
      maxPerIp: 10,
      maxPerEmail: 5,
    });
    if (!rl.ok) {
      return NextResponse.json(
        { error: "Too many requests, please wait a moment and try again." },
        { status: 429, headers: { "Retry-After": String(rl.retryAfter) } }
      );
    }

    const [user] = await db
      .select({ id: users.id })
      .from(users)
      .where(eq(users.email, email))
      .limit(1);

    if (!user) {
      // Don't reveal whether the email exists
      return NextResponse.json({ sent: true });
    }

    const code = String(Math.floor(100000 + Math.random() * 900000));
    await setOtp(email, code);

    if (process.env.NODE_ENV !== "production") {
      console.log(`[DEV] Sign-in code for ${email}: ${code}`);
      return NextResponse.json({ sent: true, devCode: code });
    }

    // Find the user's tenant for email branding
    const { tenantMemberships, adminAssignments } = await import("@accessbuddy/db");
    const [membership] = await db
      .select({ tenantId: tenantMemberships.tenantId })
      .from(tenantMemberships)
      .where(eq(tenantMemberships.userId, user.id))
      .limit(1);

    const [admin] = await db
      .select({ tenantId: adminAssignments.tenantId })
      .from(adminAssignments)
      .where(eq(adminAssignments.userId, user.id))
      .limit(1);

    // Global admins have null tenantId - fall back to first tenant
    let tenantId = membership?.tenantId ?? admin?.tenantId ?? null;
    if (!tenantId) {
      const [firstTenant] = await db.select({ id: tenants.id }).from(tenants).limit(1);
      if (firstTenant) tenantId = firstTenant.id;
    }

    const { sendTemplatedEmail, buildEmailConfig } = await import("@/lib/services/email");

    let result: import("@/lib/services/email").EmailSendResult = { sent: true };

    if (tenantId) {
      const [tenant] = await db
        .select({ id: tenants.id, name: tenants.name, settings: tenants.settings, logoUrl: tenants.logoUrl })
        .from(tenants)
        .where(eq(tenants.id, tenantId))
        .limit(1);

      if (tenant) {
        result = await withTenant(tenant.id, async (tx) => {
          const emailConfig = { ...buildEmailConfig(tenant), sendEmails: true };
          return sendTemplatedEmail(
            email,
            "verificationCode",
            { code },
            emailConfig,
            undefined,
            {
              tx,
              tenantId: tenant.id,
              entityType: AuditEntityType.MEMBER,
              entityId: user.id,
              actorId: null,
            }
          );
        });
      }
    } else {
      // No tenants exist at all - send with default branding
      result = await sendTemplatedEmail(
        email,
        "verificationCode",
        { code },
        { clubName: "AccessBuddy", sendEmails: true }
      );
    }

    // Be honest when the email did not go out: returning { sent: true } here
    // left members waiting on a sign-in code that never arrived.
    if (!result.sent) {
      return NextResponse.json(
        {
          error:
            "We could not send your sign-in code right now. Please try again in a few minutes, or contact your club if it keeps happening.",
        },
        { status: 502 }
      );
    }

    return NextResponse.json({ sent: true });
  } catch (err) {
    console.error("Send OTP error:", err);
    return NextResponse.json({ error: "Failed to send code" }, { status: 500 });
  }
}

