import { NextRequest, NextResponse } from "next/server";
import { cookies } from "next/headers";
import { eq } from "drizzle-orm";
import { db, users, adminAssignments, tenants, tenantMemberships } from "@accessbuddy/db";
import { AuditEntityType, AuditAction } from "@accessbuddy/shared";
import { verifyOtp } from "@/lib/otp-store";
import { checkRateLimitIpAndEmail, getClientIp } from "@/lib/rate-limit";
import { signWebauthnSession, SESSION_MAX_AGE_SECONDS } from "@/lib/auth";
import { z } from "zod";

const SESSION_COOKIE_NAME = "session";

const schema = z.object({
  email: z.string().email(),
  code: z.string().length(6),
});

/**
 * Platform-level OTP verification. Verifies the code, creates a session
 * cookie (same as WebAuthn login), and returns routing hints.
 *
 * Security hardening (2026-07 review):
 * - F2: removed the `isDev` Host-header code-skip that let anyone bypass
 *   code comparison entirely by spoofing `Host: localhost`.
 * - F3: the code is now checked against a hashed, single-use, attempt-capped
 *   Postgres record (see lib/otp-store.ts) instead of a plaintext in-memory
 *   Map, and this route is now rate-limited on both IP and email.
 * - F1: session cookies are signed with the dedicated SESSION_SIGNING_SECRET
 *   via lib/auth.ts's signWebauthnSession(), never CRON_SECRET or a literal.
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const parsed = schema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json({ error: "Valid email and 6-digit code required" }, { status: 400 });
    }

    const email = parsed.data.email.toLowerCase().trim();
    const ip = getClientIp(request);

    const rl = await checkRateLimitIpAndEmail("auth.verify-otp", ip, email, {
      windowSeconds: 15 * 60,
      maxPerIp: 30,
      maxPerEmail: 10,
    });
    if (!rl.ok) {
      return NextResponse.json(
        { error: "Too many attempts, please wait a moment and try again." },
        { status: 429, headers: { "Retry-After": String(rl.retryAfter) } }
      );
    }

    const result = await verifyOtp(email, parsed.data.code);
    if (result !== "valid") {
      return NextResponse.json({ error: "Invalid or expired code" }, { status: 401 });
    }

    const [user] = await db
      .select({ id: users.id, email: users.email, firebaseUid: users.firebaseUid })
      .from(users)
      .where(eq(users.email, email))
      .limit(1);

    if (!user) {
      return NextResponse.json({ error: "Invalid or expired code" }, { status: 401 });
    }

    // Create session cookie (same pattern as WebAuthn login). Always
    // signed — no unsigned/dev fallback — because auth.ts's getAuthUser
    // verifies the signature unconditionally.
    const sessionValue = signWebauthnSession({ uid: user.firebaseUid, email: user.email });

    const cookieStore = await cookies();
    cookieStore.set(SESSION_COOKIE_NAME, sessionValue, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: SESSION_MAX_AGE_SECONDS,
    });

    // Routing hints
    let isAdmin = false;
    let tenantSlug: string | null = null;
    let membershipCount = 0;

    const [admin] = await db
      .select({ tenantId: adminAssignments.tenantId })
      .from(adminAssignments)
      .where(eq(adminAssignments.userId, user.id))
      .limit(1);

    if (admin?.tenantId) {
      const [t] = await db.select({ slug: tenants.slug }).from(tenants).where(eq(tenants.id, admin.tenantId)).limit(1);
      if (t) { isAdmin = true; tenantSlug = t.slug; }
    } else if (admin && !admin.tenantId) {
      const [t] = await db.select({ slug: tenants.slug }).from(tenants).limit(1);
      if (t) { isAdmin = true; tenantSlug = t.slug; }
    }

    const memberships = await db
      .select({ tenantId: tenantMemberships.tenantId })
      .from(tenantMemberships)
      .where(eq(tenantMemberships.userId, user.id));
    membershipCount = memberships.length;

    if (!isAdmin && membershipCount > 0) {
      const [t] = await db.select({ slug: tenants.slug }).from(tenants).where(eq(tenants.id, memberships[0].tenantId)).limit(1);
      if (t) tenantSlug = t.slug;
    }

    // Audit login
    const { createAuditEntry } = await import("@/lib/services/audit");
    const loginTenantId = admin?.tenantId ?? memberships[0]?.tenantId ?? null;
    createAuditEntry(db, {
      tenantId: loginTenantId,
      entityType: AuditEntityType.MEMBER,
      entityId: user.id,
      action: AuditAction.LOGIN,
      actorId: user.id,
      actorType: "user",
      metadata: { email: user.email, method: "otp" },
      ipAddress: ip === "unknown" ? null : ip,
    }).catch(() => {});

    return NextResponse.json({ success: true, isAdmin, tenantSlug, membershipCount });
  } catch (err) {
    console.error("Verify OTP error:", err);
    return NextResponse.json({ error: "Verification failed" }, { status: 500 });
  }
}

