"use client";

import { useState, useEffect } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { startAuthentication, browserSupportsWebAuthn } from "@simplewebauthn/browser";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import Image from "next/image";
import { safeRedirect } from "@/lib/safe-redirect";

/**
 * Build an Error from a failed auth-email response, preferring the server's
 * member-facing message (e.g. "We could not send your sign-in link right
 * now...") over the generic fallback.
 */
async function errorFromResponse(res: Response, fallback: string): Promise<Error> {
  const data = await res.json().catch(() => null);
  return new Error(data?.error ?? fallback);
}

function isPwa(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(display-mode: standalone)").matches
    || ("standalone" in window.navigator && (window.navigator as { standalone?: boolean }).standalone === true);
}

export function SignInForm() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const redirectTo = safeRedirect(searchParams.get("redirect"));
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [resent, setResent] = useState(false);
  const [resendCooldown, setResendCooldown] = useState(false);
  const [passkeyAvailable, setPasskeyAvailable] = useState(false);
  const [passkeyLoading, setPasskeyLoading] = useState(false);
  const [standaloneMode, setStandaloneMode] = useState(false);
  const [otpCode, setOtpCode] = useState("");
  const [otpSent, setOtpSent] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    setStandaloneMode(isPwa());
    if (browserSupportsWebAuthn() && localStorage.getItem("passkey_prompted") === "true") {
      setPasskeyAvailable(true);
    }
  }, []);

  async function handlePasskeyLogin() {
    setPasskeyLoading(true);
    setError(null);
    try {
      const optionsRes = await fetch("/api/auth/webauthn/login");
      if (!optionsRes.ok) throw new Error("Failed to get options");
      const options = await optionsRes.json();

      const credential = await startAuthentication({ optionsJSON: options });

      const verifyRes = await fetch("/api/auth/webauthn/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(credential),
      });
      if (!verifyRes.ok) throw new Error("Authentication failed");

      routeFromResponse(await verifyRes.json());
    } catch (err) {
      if (err instanceof Error && err.name === "NotAllowedError") return;
      setError("Biometric sign-in failed. Try using your email instead.");
    } finally {
      setPasskeyLoading(false);
    }
  }

  async function handleSendCode() {
    if (!email.trim()) return;
    setLoading(true);
    setError(null);

    try {
      if (standaloneMode) {
        // PWA: send OTP code
        const res = await fetch("/api/auth/send-otp", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email: email.trim() }),
        });
        if (!res.ok) throw await errorFromResponse(res, "Failed to send code");
        setOtpSent(true);
        setSent(true);
      } else {
        // Browser: send magic link
        const res = await fetch("/api/auth/send-magic-link", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email: email.trim(), redirect: redirectTo }),
        });
        if (!res.ok) throw await errorFromResponse(res, "Failed to send sign-in link");
        window.localStorage.setItem("emailForSignIn", email.trim());
        setSent(true);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  async function handleVerifyOtp() {
    if (!otpCode.trim() || otpCode.length !== 6) return;
    setLoading(true);
    setError(null);

    try {
      const res = await fetch("/api/auth/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim(), code: otpCode.trim() }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => null);
        throw new Error(data?.error ?? "Invalid code");
      }

      routeFromResponse(await res.json());
    } catch (err) {
      setError(err instanceof Error ? err.message : "Verification failed");
    } finally {
      setLoading(false);
    }
  }

  function routeFromResponse(data: { isAdmin?: boolean; tenantSlug?: string | null }) {
    if (data.isAdmin && data.tenantSlug) {
      router.push(`/t/${data.tenantSlug}/admin`);
    } else if (data.tenantSlug) {
      router.push(`/t/${data.tenantSlug}/dashboard`);
    } else {
      router.push(redirectTo);
    }
  }

  return (
    <Card className="w-full max-w-sm">
      <CardHeader className="text-center">
        <div className="mx-auto mb-2">
          <Image src="/icon.png" alt="AccessBuddy" width={40} height={40} />
        </div>
        <CardTitle>Sign in to AccessBuddy</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {!sent ? (
          <>
            {passkeyAvailable && (
              <>
                <Button
                  className="w-full"
                  onClick={handlePasskeyLogin}
                  disabled={passkeyLoading}
                >
                  {passkeyLoading ? "Verifying..." : "Sign in with Face ID"}
                </Button>
                <div className="relative">
                  <div className="absolute inset-0 flex items-center">
                    <span className="w-full border-t" />
                  </div>
                  <div className="relative flex justify-center text-xs uppercase">
                    <span className="bg-card px-2 text-muted-foreground">or</span>
                  </div>
                </div>
              </>
            )}
            <div className="space-y-2">
              <Label htmlFor="email">Email address</Label>
              <Input
                id="email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSendCode()}
                placeholder="you@example.com"
                autoFocus
              />
            </div>
            <Button
              className="w-full"
              onClick={handleSendCode}
              disabled={loading || !email.trim()}
            >
              {loading ? "Sending..." : standaloneMode ? "Send sign-in code" : "Send sign-in link"}
            </Button>
            {error && <p className="text-sm text-destructive">{error}</p>}
            <p className="text-xs text-center text-muted-foreground">
              {standaloneMode
                ? "We will send a 6-digit code to your email."
                : "We will send a magic link to your email. No password needed."}
            </p>
          </>
        ) : otpSent ? (
          /* OTP code entry (PWA mode) */
          <div className="space-y-4 py-2">
            <div className="text-center">
              <div className="mx-auto mb-3 h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center text-2xl text-primary">
                ✉
              </div>
              <p className="text-sm font-medium">Enter your sign-in code</p>
              <p className="text-sm text-muted-foreground">
                We sent a 6-digit code to <strong>{email}</strong>
              </p>
            </div>
            <Input
              type="text"
              inputMode="numeric"
              pattern="[0-9]*"
              maxLength={6}
              placeholder="000000"
              value={otpCode}
              onChange={(e) => setOtpCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
              onKeyDown={(e) => e.key === "Enter" && handleVerifyOtp()}
              className="text-center text-2xl tracking-[0.5em] font-mono"
              autoFocus
            />
            <Button
              className="w-full"
              onClick={handleVerifyOtp}
              disabled={loading || otpCode.length !== 6}
            >
              {loading ? "Verifying..." : "Sign in"}
            </Button>
            {error && <p className="text-sm text-destructive">{error}</p>}
            <div className="flex flex-col gap-2 items-center">
              <button
                type="button"
                className="text-sm text-muted-foreground hover:text-primary transition-colors disabled:opacity-50"
                disabled={loading || resendCooldown}
                onClick={async () => {
                  setLoading(true);
                  setError(null);
                  try {
                    const res = await fetch("/api/auth/send-otp", {
                      method: "POST",
                      headers: { "Content-Type": "application/json" },
                      body: JSON.stringify({ email: email.trim() }),
                    });
                    if (!res.ok) throw await errorFromResponse(res, "Failed to resend code.");
                    setResent(true);
                    setResendCooldown(true);
                    setTimeout(() => setResendCooldown(false), 30000);
                  } catch (err) {
                    setError(err instanceof Error ? err.message : "Failed to resend code.");
                  } finally {
                    setLoading(false);
                  }
                }}
              >
                {resendCooldown ? "Code resent" : "Didn't receive a code? Resend"}
              </button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => { setSent(false); setOtpSent(false); setOtpCode(""); setError(null); }}
              >
                Use a different email
              </Button>
            </div>
          </div>
        ) : (
          /* Magic link sent (browser mode) */
          <div className="text-center space-y-3 py-4">
            <div className="mx-auto h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center text-2xl text-primary">
              ✉
            </div>
            <p className="text-sm font-medium">Check your email</p>
            <p className="text-sm text-muted-foreground">
              We sent a sign-in link to <strong>{email}</strong>
            </p>
            {resent && (
              <p className="text-sm text-primary font-medium">Link resent!</p>
            )}
            {error && <p className="text-sm text-destructive">{error}</p>}
            <div className="flex flex-col gap-2">
              <button
                type="button"
                className="text-sm text-muted-foreground hover:text-primary transition-colors disabled:opacity-50"
                disabled={loading || resendCooldown}
                onClick={async () => {
                  setLoading(true);
                  setError(null);
                  setResent(false);
                  try {
                    const res = await fetch("/api/auth/send-magic-link", {
                      method: "POST",
                      headers: { "Content-Type": "application/json" },
                      body: JSON.stringify({ email: email.trim(), redirect: redirectTo }),
                    });
                    if (!res.ok) throw await errorFromResponse(res, "Failed to resend link. Please try again.");
                    setResent(true);
                    setResendCooldown(true);
                    setTimeout(() => setResendCooldown(false), 30000);
                  } catch (err) {
                    setError(err instanceof Error ? err.message : "Failed to resend link. Please try again.");
                  } finally {
                    setLoading(false);
                  }
                }}
              >
                {loading ? "Resending..." : resendCooldown ? "Link resent" : "Didn't receive an email? Click here to resend"}
              </button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => { setSent(false); setEmail(""); setResent(false); setError(null); }}
              >
                Use a different email
              </Button>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

