51	        //   admin → admin dashboard
52	        //   single membership → member dashboard
53	        //   multiple memberships → clubs selector
54	        const isGenericRedirect =
55	          redirectTo === "/" || redirectTo === "/clubs" || redirectTo.endsWith("/dashboard");
56	
