1	import { NextRequest, NextResponse } from "next/server";
2	import { eq } from "drizzle-orm";
3	import { db, users, tenants } from "@accessbuddy/db";
4	import { AuditEntityType } from "@accessbuddy/shared";
5	import { setOtp } from "@/lib/otp-store";
6	import { checkRateLimitIpAndEmail, getClientIp } from "@/lib/rate-limit";
7	import { withTenant } from "@/lib/with-tenant";
8	import { z } from "zod";
9	
10	const schema = z.object({ email: z.string().email() });
11	
12	/**
13	 * Platform-level OTP send. Used by the PWA sign-in flow where magic links
14	 * can't transfer session cookies to the standalone app context.
15	 *
16	 * Security hardening (2026-07 review): the dev-code disclosure and rate
17	 * limiting are now gated on NODE_ENV, never on the client-controlled Host
18	 * header (F2/F3) — see lib/auth.ts's isDevLoginEnabled() note for the
19	 * Host-header exploit this class of check used to allow.
20	 */
21	export async function POST(request: NextRequest) {
22	  try {
23	    const body = await request.json();
24	    const parsed = schema.safeParse(body);
25	    if (!parsed.success) {
26	      return NextResponse.json({ error: "Valid email required" }, { status: 400 });
27	    }
28	
29	    const email = parsed.data.email.toLowerCase().trim();
30	    const ip = getClientIp(request);
31	
32	    const rl = await checkRateLimitIpAndEmail("auth.send-otp", ip, email, {
33	      windowSeconds: 60,
34	      maxPerIp: 10,
35	      maxPerEmail: 5,
36	    });
37	    if (!rl.ok) {
38	      return NextResponse.json(
39	        { error: "Too many requests, please wait a moment and try again." },
40	        { status: 429, headers: { "Retry-After": String(rl.retryAfter) } }
41	      );
42	    }
43	
44	    const [user] = await db
45	      .select({ id: users.id })
46	      .from(users)
47	      .where(eq(users.email, email))
48	      .limit(1);
49	
50	    if (!user) {
51	      // Don't reveal whether the email exists
52	      return NextResponse.json({ sent: true });
53	    }
54	
55	    const code = String(Math.floor(100000 + Math.random() * 900000));
56	    await setOtp(email, code);
57	
58	    if (process.env.NODE_ENV !== "production") {
59	      console.log(`[DEV] Sign-in code for ${email}: ${code}`);
60	      return NextResponse.json({ sent: true, devCode: code });
61	    }
62	
63	    // Find the user's tenant for email branding
64	    const { tenantMemberships, adminAssignments } = await import("@accessbuddy/db");
65	    const [membership] = await db
66	      .select({ tenantId: tenantMemberships.tenantId })
67	      .from(tenantMemberships)
68	      .where(eq(tenantMemberships.userId, user.id))
69	      .limit(1);
70	
71	    const [admin] = await db
72	      .select({ tenantId: adminAssignments.tenantId })
73	      .from(adminAssignments)
74	      .where(eq(adminAssignments.userId, user.id))
75	      .limit(1);
76	
77	    // Global admins have null tenantId - fall back to first tenant
78	    let tenantId = membership?.tenantId ?? admin?.tenantId ?? null;
79	    if (!tenantId) {
80	      const [firstTenant] = await db.select({ id: tenants.id }).from(tenants).limit(1);
81	      if (firstTenant) tenantId = firstTenant.id;
82	    }
83	
84	    const { sendTemplatedEmail, buildEmailConfig } = await import("@/lib/services/email");
85	
86	    let result: import("@/lib/services/email").EmailSendResult = { sent: true };
87	
88	    if (tenantId) {
89	      const [tenant] = await db
90	        .select({ id: tenants.id, name: tenants.name, settings: tenants.settings, logoUrl: tenants.logoUrl })
91	        .from(tenants)
92	        .where(eq(tenants.id, tenantId))
93	        .limit(1);
94	
95	      if (tenant) {
96	        result = await withTenant(tenant.id, async (tx) => {
97	          const emailConfig = { ...buildEmailConfig(tenant), sendEmails: true };
98	          return sendTemplatedEmail(
99	            email,
100	            "verificationCode",
101	            { code },
102	            emailConfig,
103	            undefined,
104	            {
105	              tx,
106	              tenantId: tenant.id,
107	              entityType: AuditEntityType.MEMBER,
108	              entityId: user.id,
109	              actorId: null,
110	            }
111	          );
112	        });
113	      }
114	    } else {
115	      // No tenants exist at all - send with default branding
116	      result = await sendTemplatedEmail(
117	        email,
118	        "verificationCode",
119	        { code },
120	        { clubName: "AccessBuddy", sendEmails: true }
121	      );
122	    }
123	
124	    // Be honest when the email did not go out: returning { sent: true } here
125	    // left members waiting on a sign-in code that never arrived.
126	    if (!result.sent) {
127	      return NextResponse.json(
128	        {
129	          error:
130	            "We could not send your sign-in code right now. Please try again in a few minutes, or contact your club if it keeps happening.",
131	        },
132	        { status: 502 }
133	      );
134	    }
135	
136	    return NextResponse.json({ sent: true });
137	  } catch (err) {
138	    console.error("Send OTP error:", err);
139	    return NextResponse.json({ error: "Failed to send code" }, { status: 500 });
140	  }
141	}
