5	import { AuditEntityType, AuditAction } from "@accessbuddy/shared";
6	import { verifyOtp } from "@/lib/otp-store";
7	import { checkRateLimitIpAndEmail, getClientIp } from "@/lib/rate-limit";
8	import { signWebauthnSession, SESSION_MAX_AGE_SECONDS } from "@/lib/auth";
9	import { z } from "zod";
10	
11	const SESSION_COOKIE_NAME = "session";
12	
13	const schema = z.object({
14	  email: z.string().email(),
15	  code: z.string().length(6),
16	});
17	
18	/**
19	 * Platform-level OTP verification. Verifies the code, creates a session
20	 * cookie (same as WebAuthn login), and returns routing hints.
21	 *
22	 * Security hardening (2026-07 review):
23	 * - F2: removed the `isDev` Host-header code-skip that let anyone bypass
24	 *   code comparison entirely by spoofing `Host: localhost`.
25	 * - F3: the code is now checked against a hashed, single-use, attempt-capped
26	 *   Postgres record (see lib/otp-store.ts) instead of a plaintext in-memory
27	 *   Map, and this route is now rate-limited on both IP and email.
28	 * - F1: session cookies are signed with the dedicated SESSION_SIGNING_SECRET
29	 *   via lib/auth.ts's signWebauthnSession(), never CRON_SECRET or a literal.
30	 */
31	export async function POST(request: NextRequest) {
32	  try {
33	    const body = await request.json();
34	    const parsed = schema.safeParse(body);
35	    if (!parsed.success) {
36	      return NextResponse.json({ error: "Valid email and 6-digit code required" }, { status: 400 });
37	    }
38	
39	    const email = parsed.data.email.toLowerCase().trim();
40	    const ip = getClientIp(request);
41	
42	    const rl = await checkRateLimitIpAndEmail("auth.verify-otp", ip, email, {
43	      windowSeconds: 15 * 60,
44	      maxPerIp: 30,
45	      maxPerEmail: 10,
46	    });
47	    if (!rl.ok) {
48	      return NextResponse.json(
49	        { error: "Too many attempts, please wait a moment and try again." },
50	        { status: 429, headers: { "Retry-After": String(rl.retryAfter) } }
51	      );
52	    }
53	
54	    const result = await verifyOtp(email, parsed.data.code);
55	    if (result !== "valid") {
56	      return NextResponse.json({ error: "Invalid or expired code" }, { status: 401 });
57	    }
58	
59	    const [user] = await db
60	      .select({ id: users.id, email: users.email, firebaseUid: users.firebaseUid })
61	      .from(users)
62	      .where(eq(users.email, email))
63	      .limit(1);
64	
65	    if (!user) {
66	      return NextResponse.json({ error: "Invalid or expired code" }, { status: 401 });
67	    }
68	
69	    // Create session cookie (same pattern as WebAuthn login). Always
70	    // signed — no unsigned/dev fallback — because auth.ts's getAuthUser
71	    // verifies the signature unconditionally.
72	    const sessionValue = signWebauthnSession({ uid: user.firebaseUid, email: user.email });
73	
74	    const cookieStore = await cookies();
75	    cookieStore.set(SESSION_COOKIE_NAME, sessionValue, {
76	      httpOnly: true,
77	      secure: process.env.NODE_ENV === "production",
78	      sameSite: "lax",
79	      path: "/",
80	      maxAge: SESSION_MAX_AGE_SECONDS,
81	    });
82	
83	    // Routing hints
84	    let isAdmin = false;
85	    let tenantSlug: string | null = null;
86	    let membershipCount = 0;
87	
88	    const [admin] = await db
89	      .select({ tenantId: adminAssignments.tenantId })
90	      .from(adminAssignments)
91	      .where(eq(adminAssignments.userId, user.id))
92	      .limit(1);
93	
94	    if (admin?.tenantId) {
95	      const [t] = await db.select({ slug: tenants.slug }).from(tenants).where(eq(tenants.id, admin.tenantId)).limit(1);
96	      if (t) { isAdmin = true; tenantSlug = t.slug; }
97	    } else if (admin && !admin.tenantId) {
98	      const [t] = await db.select({ slug: tenants.slug }).from(tenants).limit(1);
99	      if (t) { isAdmin = true; tenantSlug = t.slug; }
100	    }
101	
102	    const memberships = await db
103	      .select({ tenantId: tenantMemberships.tenantId })
104	      .from(tenantMemberships)
105	      .where(eq(tenantMemberships.userId, user.id));
106	    membershipCount = memberships.length;
107	
108	    if (!isAdmin && membershipCount > 0) {
109	      const [t] = await db.select({ slug: tenants.slug }).from(tenants).where(eq(tenants.id, memberships[0].tenantId)).limit(1);
110	      if (t) tenantSlug = t.slug;
111	    }
112	
113	    // Audit login
114	    const { createAuditEntry } = await import("@/lib/services/audit");
115	    const loginTenantId = admin?.tenantId ?? memberships[0]?.tenantId ?? null;
116	    createAuditEntry(db, {
117	      tenantId: loginTenantId,
118	      entityType: AuditEntityType.MEMBER,
119	      entityId: user.id,
120	      action: AuditAction.LOGIN,
121	      actorId: user.id,
122	      actorType: "user",
123	      metadata: { email: user.email, method: "otp" },
124	      ipAddress: ip === "unknown" ? null : ip,
125	    }).catch(() => {});
126	
127	    return NextResponse.json({ success: true, isAdmin, tenantSlug, membershipCount });
128	  } catch (err) {
129	    console.error("Verify OTP error:", err);
130	    return NextResponse.json({ error: "Verification failed" }, { status: 500 });
131	  }
132	}
