10	    return adminApp;
11	  }
12	
13	  const projectId = process.env.FIREBASE_PROJECT_ID ?? process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID;
14	
15	  if (process.env.FIREBASE_SERVICE_ACCOUNT_KEY) {
