  date: string; // YYYY-MM-DD local
  min?: number;
  max?: number;
  precis?: string;
  rainChance?: string; // e.g. "30%"
  rainRange?: string; // e.g. "0 to 2 mm"
  forecast?: string; // full text from IDV10752
  wind?: string;
  uv?: string;
  fireDanger?: string;
};

export type BomFeed = {
  format: "lsv-bom-weather";
  issued: string; // issue-time-local of IDV10753
  issuedUtc: string;
  fetchedAt: string;
  towns: Record<string, DayForecast[]>;
  metro: Record<string, DayForecast[]>;
};

const parser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: "@_",
  processEntities: false, // no entity expansion: closes the XXE class
  allowBooleanAttributes: true,
  parseTagValue: false,
  isArray: (name) => ["area", "forecast-period", "element", "text"].includes(name),
});

type Node = Record<string, unknown>;

function asArray<T>(v: T | T[] | undefined): T[] {
  if (v === undefined) return [];
  return Array.isArray(v) ? v : [v];
}

function localDate(startTimeLocal: string): string {
  // "2026-11-17T00:00:00+11:00" -> "2026-11-17" (the local date is in the string)
  return startTimeLocal.slice(0, 10);
}

function areas(xml: string, type: string): Node[] {
  const root = parser.parse(xml) as Node;
  const product = root.product as Node;
  const forecast = product?.forecast as Node | undefined;
  return asArray(forecast?.area as Node[] | undefined).filter((a) => a["@_type"] === type);
}

function issueTime(xml: string): { local: string; utc: string } {
  const root = parser.parse(xml) as Node;
  const amoc = (root.product as Node)?.amoc as Node;
  return { local: String(amoc?.["issue-time-local"] ?? ""), utc: String(amoc?.["issue-time-utc"] ?? "") };
}

function periods(area: Node): Node[] {
  return asArray(area["forecast-period"] as Node[] | undefined);
}

function textOf(period: Node, type: string): string | undefined {
  const t = asArray(period.text as Node[] | undefined).find((x) => x["@_type"] === type);
  return t ? String(t["#text"] ?? "").trim() || undefined : undefined;
}

function elementOf(period: Node, type: string): string | undefined {
  const e = asArray(period.element as Node[] | undefined).find((x) => x["@_type"] === type);
  return e ? String(e["#text"] ?? "").trim() || undefined : undefined;
}

export function parsePrecis(xml: string): Record<string, DayForecast[]> {
  const out: Record<string, DayForecast[]> = {};
  for (const area of areas(xml, "location")) {
    const name = String(area["@_description"]);
    const days: DayForecast[] = [];
    for (const p of periods(area)) {
      const d: DayForecast = { date: localDate(String(p["@_start-time-local"])) };
      const min = elementOf(p, "air_temperature_minimum");
      const max = elementOf(p, "air_temperature_maximum");
      if (min !== undefined) d.min = Number(min);
      if (max !== undefined) d.max = Number(max);
      d.precis = textOf(p, "precis");
      d.rainChance = textOf(p, "probability_of_precipitation");
      d.rainRange = elementOf(p, "precipitation_range");
      days.push(d);
    }
