const sheetHrs = v => v && v[0] ? (v[0][1] ? `${v[0][0]}-${v[0][1]}` : v[0][0]) : "";
function planImport(p) {
  const plan = { units: {}, ask: [], stats: { services: 0, changedDays: 0 }, events: [], weather: {}, contacts: null, sites: p.sites };
  for (const [code, data] of Object.entries(p.daily)) {
    const u = S.units[code]; if (!u || u.linkedTo) continue; plan.stats.services++;
    const { rules, adj } = compressDaily(data);
    const dates = Object.keys(data).sort(), first = dates[0], last = dates.at(-1);
