import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { APP_CLAIM, memberClaims, noClaims, roleFromClaims } from "../src/lib/claims";

const read = (p: string) => readFileSync(resolve(import.meta.dir, "..", p), "utf8");

describe("app-scoped sign-in claim", () => {
  test("members get exactly poc_oss and name, never bare member/admin", () => {
    expect(APP_CLAIM).toBe("poc_oss");
    expect(memberClaims("member", "A B")).toEqual({ poc_oss: "member", name: "A B" });
    expect(memberClaims("admin", "A B")).toEqual({ poc_oss: "admin", name: "A B" });
    expect(noClaims()).toEqual({});
  });
  test("only the two roles are recognised; bare claims are not", () => {
    expect(roleFromClaims({ poc_oss: "member" })).toBe("member");
    expect(roleFromClaims({ poc_oss: "admin" })).toBe("admin");
    expect(roleFromClaims({ member: true, admin: true })).toBeNull();
    expect(roleFromClaims({ poc_oss: "owner" })).toBeNull();
    expect(roleFromClaims({ poc_other: "admin" })).toBeNull();
    expect(roleFromClaims(undefined)).toBeNull();
  });
  test("every reader uses the same claim name and none reads the bare claims", () => {
    const rules = read("firestore.rules");
    expect(rules).toContain("request.auth.token.get('poc_oss', '') in ['member', 'admin']");
    expect(rules).toContain("request.auth.token.get('poc_oss', '') == 'admin'");
    expect(rules).not.toMatch(/token\.member\b|token\.admin\b/);
    const bridge = read("src/bridge/bridge.ts");
    expect(bridge).toContain("claims.poc_oss");
    expect(bridge).not.toMatch(/claims\.member\b/);
    for (const f of ["src/lib/members.ts", "src/app/api/auth/firebase-token/route.ts"]) {
      expect(read(f)).not.toMatch(/member: (true|false)/);
      expect(read(f)).toContain("memberClaims(");
    }
  });
});
EOF
bunx tsc --noEmit; echo tsc=$?; bun test 2>&1 | tail -4

