20	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
21	  }
22	  const user = await getAuthUser();
23	  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
24	  const token = await getAdminAuth().createCustomToken(user.uid, memberClaims(user.role, user.displayName));
25	  return NextResponse.json({ token }, { headers: { "Cache-Control": "no-store" } });
26	}

