---
variable "app_id" {
  description = "The POC's id. Every resource name in this module derives from it."
  type        = string
  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,18}[a-z0-9]$", var.app_id)) && !strcontains(var.app_id, "--") && !contains(["hub", "www", "api", "admin", "platform", "auth", "mail"], var.app_id)
    error_message = "app_id is lowercase dns-safe, 3 to 20 characters, no double hyphen, and not reserved."
  }
}

variable "display_name" {
  type = string
}

variable "project_id" {
  type = string
}

variable "region" {
  type    = string
  default = "australia-southeast1"
}

variable "poc_domain" {
  type    = string
  default = "poc.nicholaswood.com.au"
}

variable "site_prefix" {
  description = "Firebase Hosting site ids are global; the site is <site_prefix>-<app_id>."
  type        = string
  default     = "lsv-poc"
}

# From terraform/platform outputs.
variable "dns_zone_name" {
  description = "platform output dns_zone_name (the delegated sub-zone)"
  type        = string
}

variable "workload_identity_pool_id" {
  description = "platform output workload_identity_pool"
  type        = string
  default     = "github"
}

variable "notification_channel" {
  description = "platform output notification_channel"
  type        = string
}

variable "firebase_api_key" {
  description = "platform output firebase_api_key (public)"
  type        = string
}

variable "firebase_app_id" {
  description = "platform output firebase_app_id (public)"
  type        = string
}

# GitHub, by numeric id: survives renames and cannot be claimed by
# re-registering an old name.
variable "github_repository_id" {
  type = string
}

variable "github_owner_id" {
  type = string
}

variable "client_access" {
  description = "True only for a POC whose browser talks to Firestore directly (dataModel client-access). Adds the custom-token signing grant."
  type        = bool
  default     = false
}

variable "scheduled_jobs" {
  description = "From poc.json scheduledJobs. Empty means no scheduler jobs and no job-failure alert."
  type = list(object({
    name     = string
    schedule = string
    path     = string
  }))
  default = []
}

variable "initial_image" {
  description = "Image for the first apply; CI replaces it and Terraform ignores the drift."
  type        = string
  default     = "us-docker.pkg.dev/cloudrun/container/hello"
}

variable "signin_failure_threshold" {
  description = "Refused sign-ins in 10 minutes that raise an alert."
  type        = number
  default     = 20
}

variable "error_rate_threshold" {
  description = "5xx responses per second, averaged over 5 minutes, that raise an alert."
  type        = number
  default     = 0.05
}
