=== claims.ts
/**
 * The claim contract shared by every LSV POC and the hub.
 *
 *   custom claim  poc_<appId>  =  "member" | "admin"
 *
 * Nothing else grants access. A bare `member` or `admin` claim (the shape
 * Permission Assist used while it had its own project) grants nothing here,
 * and a claim for one app grants nothing in another. The Service Summary's
 * `src/lib/claims.ts` defines `poc_oss` with exactly these values, so it can
 * consume this package without changing its claim.
 *
 * The hub is the only writer of these claims (see apps/hub). Writers must
 * merge with withAppClaim(): claims are one object per user, shared by every
 * POC in the project, and a writer that replaces the object wipes the user's
 * access to every other POC.
 */
export type AppRole = "member" | "admin";

/** Lowercase, dns-safe, 3 to 20 characters, no edge hyphen. Every per-app resource name derives from it. */
export const APP_ID_PATTERN = /^[a-z][a-z0-9-]{1,18}[a-z0-9]$/;
/** Names the platform keeps for itself (hub apex, likely future hosts). */
export const RESERVED_APP_IDS = new Set(["hub", "www", "api", "admin", "platform", "auth", "mail"]);

export function isValidAppId(id: unknown): id is string {
  return typeof id === "string" && APP_ID_PATTERN.test(id) && !RESERVED_APP_IDS.has(id) && !id.includes("--");
}

export function assertAppId(id: string): string {
  if (!isValidAppId(id)) throw new Error(`Invalid app id "${id}": lowercase dns-safe, 3 to 20 characters, not reserved`);
  return id;
}

export function appClaimName(appId: string): `poc_${string}` {
  return `poc_${assertAppId(appId)}`;
}

export function parseRole(value: unknown): AppRole | null {
  return value === "member" || value === "admin" ? value : null;
}

/** The caller's role in this app, or null. Reads only `poc_<appId>`. */
export function roleFromClaims(claims: Record<string, unknown> | null | undefined, appId: string): AppRole | null {
  if (!claims) return null;
  return parseRole(claims[appClaimName(appId)]);
}

/** Firebase rejects custom claims whose JSON exceeds 1000 bytes. */
export const MAX_CLAIMS_BYTES = 1000;

/**
 * The user's claims with one app's entry set (role) or removed (null),
 * every other claim kept. Throws before Firebase would.
 */
export function withAppClaim(existing: Record<string, unknown> | null | undefined, appId: string, role: AppRole | null): Record<string, unknown> {
  const name = appClaimName(appId);
  const next: Record<string, unknown> = { ...(existing ?? {}) };
  if (role) next[name] = role;
  else delete next[name];
  const size = new TextEncoder().encode(JSON.stringify(next)).length;
  if (size > MAX_CLAIMS_BYTES) throw new Error(`Custom claims would be ${size} bytes, over Firebase's ${MAX_CLAIMS_BYTES} byte limit`);
  return next;
}

/** True when `have` satisfies `need` (admin implies member). */
export function roleSatisfies(have: AppRole, need: AppRole): boolean {
  return need === "member" ? true : have === "admin";
}
