    const hit = cache.get(uid);
    if (hit && Date.now() - hit.at < ttlMs) return hit.value;
    const snap = await db().collection(ACCESS_OVERRIDE_COLLECTION).doc(uid).get();
    const d = snap.data();
    const value = snap.exists && d && typeof d.updatedAt === "number" ? { role: parseRole(d.role), updatedAt: d.updatedAt } : null;
    cache.set(uid, { at: Date.now(), value });
    return value;
  };
}

/** Firestore store for the rate limiter (`rateLimitBuckets`), one transaction per check across instances. */
export class FirestoreRateLimitStore implements RateLimitStore {
  constructor(private db: () => Firestore) {}
  now() {
    return Date.now();
  }
  async increment(key: string, windowMs: number) {
    const ref = this.db().collection("rateLimitBuckets").doc(key);
    const now = Date.now();
    return this.db().runTransaction(async (tx) => {
      const snap = await tx.get(ref);
      const d = snap.exists ? (snap.data() as { count: number; resetAt: number }) : null;
      if (!d || d.resetAt <= now) {
        const next = { count: 1, resetAt: now + windowMs };
        tx.set(ref, next);
        return next;
      }
      tx.update(ref, { count: d.count + 1 });
      return { count: d.count + 1, resetAt: d.resetAt };
    });
  }
}
