/**
 * Fixed-window rate limiter. Ported from Permission Assist
 * host/src/lib/rate-limit.ts (the Firestore twin of AccessBuddy's
 * rate_limit_buckets), with the store made injectable for tests and the
 * client address taken from the trusted end of X-Forwarded-For.
 * Kill switch: RATE_LIMIT_DISABLED=1.
 */

/**
 * The client address, counted from the right of X-Forwarded-For.
 *
 * The first hop is whatever the client chose to send, so trusting it (as the
 * reference did) lets anyone rotate it to dodge limits. Each proxy appends
 * the address it saw, so the right-most entries are written by
 * infrastructure. `trustedProxyHops` is how many of those right-most
 * entries belong to our own proxies: behind Firebase Hosting then the Cloud
 * Run front end that is 1 (Hosting appends the client, the front end
 * appends Hosting). Confirm on the first live deploy by logging the header
 * (see DEPLOY.md); if the chain is shorter than expected the result is
 * "unknown", which shares one bucket and so fails safe.
 */
export function getClientIp(request: Request, trustedProxyHops = Number(process.env.TRUSTED_PROXY_HOPS ?? 1)): string {
  const fwd = request.headers.get("x-forwarded-for");
  if (!fwd) return "unknown";
  const hops = fwd.split(",").map((s) => s.trim()).filter(Boolean);
  const i = hops.length - 1 - Math.max(0, trustedProxyHops);
  return i >= 0 ? hops[i] : "unknown";
}

export type RateLimitResult = { ok: boolean; remaining: number; retryAfter: number };
export type RateLimitOptions = { namespace: string; windowSeconds: number; max: number };

export interface RateLimitStore {
  /** Atomically increment the bucket; start a new window when it has expired. */
  increment(key: string, windowMs: number): Promise<{ count: number; resetAt: number }>;
  now(): number;
}

export class MemoryRateLimitStore implements RateLimitStore {
  private buckets = new Map<string, { count: number; resetAt: number }>();
  constructor(private clock: () => number = Date.now) {}
  now() {
    return this.clock();
  }
  async increment(key: string, windowMs: number) {
    const now = this.clock();
    const b = this.buckets.get(key);
    const next = !b || b.resetAt <= now ? { count: 1, resetAt: now + windowMs } : { count: b.count + 1, resetAt: b.resetAt };
    this.buckets.set(key, next);
    return next;
  }
}

export function createRateLimiter(store: RateLimitStore) {
  return {
    async check(key: string, o: RateLimitOptions): Promise<RateLimitResult> {
      if (process.env.RATE_LIMIT_DISABLED === "1") return { ok: true, remaining: o.max, retryAfter: 0 };
      const now = store.now();
      const r = await store.increment(encodeURIComponent(`${o.namespace}:${key}`), o.windowSeconds * 1000);
      if (r.count > o.max) return { ok: false, remaining: 0, retryAfter: Math.max(1, Math.ceil((r.resetAt - now) / 1000)) };
      return { ok: true, remaining: Math.max(0, o.max - r.count), retryAfter: 0 };
    },
  };
}
export type RateLimiter = ReturnType<typeof createRateLimiter>;

