import { readFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { createAccessGate, createLogger, createRateLimiter, createSessionExchange } from "@lsv-poc/poc-auth";
import { appDb, firestoreOverrideReader, FirestoreRateLimitStore, verifyIdToken } from "@lsv-poc/poc-auth/firebase";
import config from "../../poc.config.json";
import { createHostHandlers, type KeyValueStore } from "./handlers";

/**
 * Production wiring, built lazily so `next build` needs no credentials.
 * poc.config.json is written by the poc-deploy scaffold from poc.json.
 * This host makes no Firebase Auth admin call: ID tokens are verified with
 * public keys, and revokes arrive as platformAccess/<uid> from the hub.
 */
export const appId = process.env.APP_ID ?? config.appId;
export const log = createLogger(appId);
const secret = () => process.env.SESSION_SIGNING_SECRET ?? "";
const origin = () => process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";
const SITE_DIR = resolve(process.env.SITE_DIR ?? join(process.cwd(), "site"));

function kv(collection: string): KeyValueStore {
  const col = () => appDb().collection(collection);
  const id = (k: string) => encodeURIComponent(k);
  return {
    async get(k) {
      const s = await col().doc(id(k)).get();
      return s.exists ? (s.data()!.value ?? null) : null;
    },
    async set(k, value) {
      await col().doc(id(k)).set({ key: k, value, updatedAt: new Date().toISOString() });
    },
    async delete(k) {
      await col().doc(id(k)).delete();
    },
    async list(prefix) {
      const s = await col().where("key", ">=", prefix).where("key", "<", prefix + "").limit(500).get();
      return s.docs.map((d) => d.data().key as string);
    },
  };
}

const settingsStore: KeyValueStore = {
  ...kv("settings"),
  async get(k) {
    const s = await appDb().collection("settings").doc(k).get();
    return s.exists ? s.data()! : null;
  },
  async set(k, v) {
    await appDb().collection("settings").doc(k).set(v as Record<string, unknown>);
  },
};

let _h: ReturnType<typeof createHostHandlers> | null = null;
export function handlers() {
  _h ??= createHostHandlers({
    appId,
    appName: config.name,
    origin: origin(),
    gate: createAccessGate({ appId, secret, readOverride: firestoreOverrideReader(() => appDb()) }),
    readSiteFile: async (name) => {
      const full = resolve(SITE_DIR, name);
      if (!full.startsWith(SITE_DIR + "/")) return null;
      return readFile(full).catch(() => null);
    },
    settings: settingsStore,
    bridge: kv("bridgeStorage"),
    bridgeEnabled: config.capabilities.length > 0,
    log,
    version: process.env.NEXT_PUBLIC_APP_VERSION ?? "dev",
  });
  return _h;
}

let _x: ReturnType<typeof createSessionExchange> | null = null;
export function sessionExchange() {
  _x ??= createSessionExchange({
    appId,
    secret,
    verifyIdToken,
    rateLimiter: createRateLimiter(new FirestoreRateLimitStore(() => appDb())),
    log,
    secureCookie: process.env.NODE_ENV === "production",
  });
  return _x;
}
