import { buildCsp, inlineScriptHashes, readCookie, SITE_HEADERS, type AccessResult, type AppRole, type Logger } from "@lsv-poc/poc-auth";

/**
 * The per-POC host, framework-free (Web Request -> Response). The Next.js
 * route files are one-line wrappers. Site serving is ported from Permission
 * Assist host/src/app/[[...path]]/route.ts and host/src/lib/site.ts; the page
 * is read from the image's site/ folder instead of a private bucket.
 */
export interface KeyValueStore {
  get(key: string): Promise<unknown | null>;
  set(key: string, value: unknown): Promise<void>;
  delete(key: string): Promise<void>;
  list(prefix: string): Promise<string[]>;
}

export type HostDeps = {
  appId: string;
  appName: string;
  origin: string;
  gate: { check(cookie: string | undefined, need: AppRole): Promise<AccessResult> };
  readSiteFile: (name: string) => Promise<Buffer | null>;
  /** settings/<doc> in the POC's own database. */
  settings: KeyValueStore;
  /** bridgeStorage/<key> in the POC's own database. */
  bridge: KeyValueStore;
  bridgeEnabled: boolean;
  log: Logger;
  version: string;
};

const CONTENT_TYPES: Record<string, string> = {
  html: "text/html; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  mjs: "text/javascript; charset=utf-8",
  css: "text/css; charset=utf-8",
  json: "application/json; charset=utf-8",
  svg: "image/svg+xml",
  png: "image/png",
  jpg: "image/jpeg",
  webp: "image/webp",
  ico: "image/x-icon",
  woff2: "font/woff2",
  txt: "text/plain; charset=utf-8",
  csv: "text/csv; charset=utf-8",
};

export function contentTypeFor(name: string): string | null {
  const ext = name.includes(".") ? name.split(".").pop()!.toLowerCase() : "";
  return CONTENT_TYPES[ext] ?? null;
}

/** Ported verbatim in intent from Permission Assist resolveObject: plain segments, known types only. */
export function resolveObject(segments: string[] | undefined): string | null {
  const parts = (segments ?? []).filter((s) => s !== "");
  if (parts.length === 0) return "index.html";
  if (parts.length > 6) return null;
  for (const p of parts) if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,100}$/.test(p) || p.includes("..")) return null;
  const name = parts.join("/");
  return contentTypeFor(name) ? name : null;
}

const BRIDGE_TAG = '<script src="/poc-bridge.js"></script>';
/** Bridge first, so window.claude exists before any page script runs. */
export function injectBridge(html: string): string {
  const head = /<head[^>]*>/i.exec(html);
  if (head) return html.slice(0, head.index + head[0].length) + BRIDGE_TAG + html.slice(head.index + head[0].length);
  return BRIDGE_TAG + html;
}

export function createHostHandlers(d: HostDeps) {
  const respond = (body: BodyInit | null, status: number, headers: Record<string, string> = {}) =>
    new Response(body, { status, headers: { ...SITE_HEADERS, "Cache-Control": "private, no-store", ...headers } });
  const json = (status: number, body: unknown) => respond(JSON.stringify(body), status, { "Content-Type": "application/json" });
  const message = (status: number, title: string, text: string) =>
    respond(`<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><title>${title}</title></head><body><h1>${title}</h1><p>${text}</p></body></html>`, status, {
      "Content-Type": "text/html; charset=utf-8",
      "Content-Security-Policy": "default-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'",
    });
  const toSignIn = () => respond(null, 303, { Location: `${d.origin}/sign-in` });
  const sameOrigin = (r: Request) => r.headers.get("origin") === new URL(d.origin).origin;

  async function page(request: Request, need: AppRole) {
    const a = await d.gate.check(readCookie(request.headers.get("cookie")), need);
    if (!a.ok && a.status === 401) return { res: toSignIn() };
    if (!a.ok) return { res: message(a.status, a.status === 403 ? "No access" : "Unavailable", a.status === 403 ? "Your access does not include this page." : "Try again shortly.") };
    return { user: a.user };
  }
  async function api(request: Request, need: AppRole, mutating = false) {
    if (mutating && !sameOrigin(request)) return { res: json(403, { error: "Forbidden" }) };
    const a = await d.gate.check(readCookie(request.headers.get("cookie")), need);
    if (!a.ok) return { res: json(a.status, { error: a.reason }) };
    return { user: a.user };
  }

  return {
    health: () => json(200, { ok: true, app: d.appId, version: d.version, time: new Date().toISOString() }),

    /** Every non sign-in path: session first, then path, then bytes. */
    async site(request: Request, segments: string[] | undefined) {
      const g = await page(request, "member");
      if (g.res) return g.res;
      const name = resolveObject(segments);
      if (!name) return message(404, "Not found", "There is nothing at this address.");
      let body: Buffer | null;
      try {
        body = await d.readSiteFile(name);
      } catch (err) {
        d.log.error("site read failed", { err, name });
        return message(502, "Temporarily unavailable", "Try again shortly.");
      }
      if (!body) return message(404, "Not found", "There is nothing at this address.");
      if (name.endsWith(".html")) {
        const html = d.bridgeEnabled ? injectBridge(body.toString("utf8")) : body.toString("utf8");
        return respond(html, 200, { "Content-Type": CONTENT_TYPES.html, "Content-Security-Policy": buildCsp(inlineScriptHashes(html)) });
      }
      return respond(new Uint8Array(body), 200, { "Content-Type": contentTypeFor(name)!, "Cache-Control": "private, no-cache" });
    },

    /** The POC admin window: a working placeholder that edits settings/app. Admin role only. */
    async adminPage(request: Request) {
      const g = await page(request, "admin");
      if (g.res) return g.res;
      const script = `(async()=>{const t=document.getElementById("s"),m=document.getElementById("m");const r=await fetch("/api/admin/settings");const j=await r.json();t.value=JSON.stringify(j.settings||{},null,2);document.getElementById("f").addEventListener("
      const html = `<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${d.appName} settings</title></head><body style="font:16px system-ui;max-width:720px;margin:24px auto;pa
      return respond(html, 200, { "Content-Type": CONTENT_TYPES.html, "Content-Security-Policy": buildCsp(inlineScriptHashes(html)) });
    },

    async settingsGet(request: Request) {
      const g = await api(request, "admin");
      if (g.res) return g.res;
      const doc = (await d.settings.get("app")) as { settings?: unknown } | null;
      return json(200, { settings: doc?.settings ?? {} });
    },

    async settingsPut(request: Request) {
      const g = await api(request, "admin", true);
      if (g.res) return g.res;
      const b = (await request.json().catch(() => null)) as { settings?: unknown } | null;
      if (!b || typeof b.settings !== "object" || b.settings === null || Array.isArray(b.settings)) return json(400, { error: "settings object required" });
      if (JSON.stringify(b.settings).length > 64_000) return json(413, { error: "settings too large" });
      await d.settings.set("app", { settings: b.settings, updatedBy: g.user!.email, updatedAt: new Date().toISOString() });
      d.log.info("settings updated", { event: "poc.settings_updated", by: g.user!.email });
      return json(200, { ok: true });
    },

    /** window.claude.storage replacement: per user, or shared across the POC's members. */
    async bridgeStorage(request: Request) {
      if (!d.bridgeEnabled) return json(404, { error: "Bridge not enabled" });
      const mutating = request.method !== "GET";
      const g = await api(request, "member", mutating);
      if (g.res) return g.res;
      const url = new URL(request.url);
      const b = mutating ? ((await request.json().catch(() => null)) as { key?: unknown; value?: unknown; shared?: unknown } | null) : null;
      const key = String(mutating ? b?.key ?? "" : url.searchParams.get("key") ?? "");
      const shared = mutating ? b?.shared === true : url.searchParams.get("shared") === "true";
      const prefix = url.searchParams.get("prefix");
      const scope = shared ? "shared:" : `user:${g.user!.uid}:`;
      if (request.method === "GET" && prefix !== null) return json(200, { keys: (await d.bridge.list(scope + prefix)).map((k) => k.slice(scope.length)) });
      if (!/^[\w.:/-]{1,200}$/.test(key)) return json(400, { error: "key required (letters, digits, . : / - _)" });
      if (request.method === "GET") return json(200, { key, value: await d.bridge.get(scope + key) });
      if (request.method === "DELETE") {
        await d.bridge.delete(scope + key);
        return json(200, { ok: true });
      }
      if (JSON.stringify(b?.value ?? null).length > 500_000) return json(413, { error: "value too large" });
      await d.bridge.set(scope + key, b?.value ?? null);
      return json(200, { ok: true });
    },

    /** window.claude user identity replacement. */
    async bridgeUser(request: Request) {
      const g = await api(request, "member");
      if (g.res) return g.res;
      return json(200, { id: g.user!.uid, email: g.user!.email, role: g.user!.role });
    },
  };
}
