"use client";

import { sendSignInLinkToEmail } from "firebase/auth";
import { useState } from "react";
import { auth } from "@/lib/firebase-client";

/** Email-link sign-in, sent by Firebase. Passwords are off. */
export default function SignIn() {
  const [email, setEmail] = useState("");
  const [state, setState] = useState<"idle" | "sending" | "sent" | "error">("idle");

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setState("sending");
    try {
      const redirect = new URLSearchParams(window.location.search).get("redirect") ?? "/";
      await sendSignInLinkToEmail(auth, email, {
        url: `${window.location.origin}/auth/callback?redirect=${encodeURIComponent(redirect)}`,
        handleCodeInApp: true,
      });
      window.localStorage.setItem("emailForSignIn", email);
      setState("sent");
    } catch {
      setState("error");
    }
  }

  return (
    <>
      <h1>Sign in</h1>
      {state === "sent" ? (
        <p>Check your email for a sign-in link. It can be used once.</p>
      ) : (
        <form onSubmit={submit}>
          <label>
            Email <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="email" />
          </label>{" "}
          <button disabled={state === "sending"}>Send link</button>
          {state === "error" && <p className="error">We could not send the link. Try again shortly.</p>}
        </form>
      )}
    </>
  );
}
