"use client";

import { isSignInWithEmailLink, signInWithEmailLink, signOut } from "firebase/auth";
import { useEffect, useState } from "react";
import { auth } from "@/lib/firebase-client";

/** Completes the email link, exchanges the ID token for the __session cookie, then drops the Firebase client session. */
export default function Callback() {
  const [message, setMessage] = useState("Signing you in…");

  useEffect(() => {
    (async () => {
      const href = window.location.href;
      if (!isSignInWithEmailLink(auth, href)) return setMessage("This sign-in link is not valid.");
      const email = window.localStorage.getItem("emailForSignIn") ?? window.prompt("Confirm your email") ?? "";
      try {
        const cred = await signInWithEmailLink(auth, email, href);
        const res = await fetch("/api/auth/session", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ idToken: await cred.user.getIdToken() }),
        });
        await signOut(auth);
        window.localStorage.removeItem("emailForSignIn");
        if (res.status === 403) return setMessage("You do not have access here. Ask the platform administrator to allocate it to you in the hub.");
        if (!res.ok) return setMessage("Sign-in failed. Try again.");
        const redirect = new URLSearchParams(window.location.search).get("redirect") ?? "/";
        window.location.replace(redirect.startsWith("/") && !redirect.startsWith("//") ? redirect : "/");
      } catch {
        setMessage("This link has expired or was already used. Request a new one.");
      }
    })();
  }, []);

  return <p>{message}</p>;
}
