/**
 * One JSON object per line on stdout, which Cloud Run hands to Cloud Logging
 * as jsonPayload with `severity` mapped. Every line carries `app_id`, so the
 * per-app log-based metrics in terraform/modules/poc-app can filter on
 * jsonPayload.app_id and jsonPayload.event.
 */
export type Severity = "DEBUG" | "INFO" | "WARNING" | "ERROR";
export type Fields = Record<string, unknown>;

export function createLogger(appId: string, sink: (line: string) => void = (l) => process.stdout.write(l + "\n")) {
  function emit(severity: Severity, message: string, fields: Fields = {}) {
    const out: Fields = { time: new Date().toISOString() };
    for (const [k, v] of Object.entries(fields)) out[k] = v instanceof Error ? `${v.name}: ${v.message}` : v;
    out.severity = severity;
    out.message = message;
    out.app_id = appId; // last, so a caller cannot overwrite it
    sink(JSON.stringify(out));
  }
  return {
    debug: (m: string, f?: Fields) => emit("DEBUG", m, f),
    info: (m: string, f?: Fields) => emit("INFO", m, f),
    warn: (m: string, f?: Fields) => emit("WARNING", m, f),
    error: (m: string, f?: Fields) => emit("ERROR", m, f),
  };
}
export type Logger = ReturnType<typeof createLogger>;

/** Event names the Terraform log-based metrics match. Change both together. */
export const LOG_EVENTS = {
  signInFailed: "auth.signin_failed",
  signInOk: "auth.signin_ok",
  jobFailed: "job.failed",
} as const;
import { createHash } from "node:crypto";

/**
 * Content security policy for a packaged POC page. Ported from Permission
 * Assist host/src/lib/site.ts (inlineScriptHashes, buildCsp, SITE_HEADERS).
 * Difference: connect-src is 'self' rather than 'none', so a page whose
 * window.claude calls were replaced by the backend bridge can reach its own
 * host. No external origin is ever allowed: libraries are vendored.
 */
export function inlineScriptHashes(html: string): string[] {
  const out: string[] = [];
  const re = /<script\b([^>]*)>([\s\S]*?)<\/script>/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(html))) {
    const attrs = m[1];
    if (/\bsrc\s*=/i.test(attrs)) continue;
    const type = /\btype\s*=\s*["']?([^"'\s>]+)/i.exec(attrs)?.[1]?.toLowerCase();
    if (type && type !== "text/javascript" && type !== "module") continue;
    const text = m[2].replace(/\r\n?/g, "\n");
    out.push(`'sha256-${createHash("sha256").update(text, "utf8").digest("base64")}'`);
  }
  return out;
}

export function buildCsp(scriptHashes: string[], opts: { connectSelf?: boolean } = {}): string {
  return [
    "default-src 'none'",
    `script-src ${["'self'", ...scriptHashes].join(" ")}`,
    "style-src 'self' 'unsafe-inline'",
    "img-src 'self' data: blob:",
    "font-src 'self' data:",
    `connect-src ${opts.connectSelf === false ? "'none'" : "'self'"}`,
    "frame-src 'none'",
    "worker-src 'self' blob:",
    "manifest-src 'none'",
    "object-src 'none'",
    "base-uri 'none'",
    "form-action 'self'",
    "frame-ancestors 'none'",
  ].join("; ");
}

/** Every source expression in a policy that names somewhere other than this origin. */
export function externalOriginsIn(csp: string): string[] {
  const out: string[] = [];
  for (const directive of csp.split(";")) {
    const [, ...sources] = directive.trim().split(/\s+/);
    for (const s of sources) {
      if (s.startsWith("'")) continue; // keywords, nonces, hashes
      if (s === "data:" || s === "blob:") continue; // same-document schemes
      out.push(s);
    }
  }
  return out;
}

/** Headers on every response from a POC page handler, whatever the status. */
export const SITE_HEADERS: Record<string, string> = {
  "X-Robots-Tag": "noindex, nofollow",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "no-referrer",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
  "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
  "Cross-Origin-Opener-Policy": "same-origin",
  "Cross-Origin-Resource-Policy": "same-origin",
  Vary: "Cookie",
};

/** Static headers for the Next.js `headers()` config (sign-in pages and API). Ported from next.config.ts. */
export const BASE_SECURITY_HEADERS = [
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "X-Frame-Options", value: "DENY" },
  { key: "X-Robots-Tag", value: "noindex, nofollow" },
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=()" },
  { key: "Strict-Transport-Security", value: "max-age=31536000; includeSubDomains" },
];

/**
 * Policy for the Next.js sign-in pages (and the hub's own pages). Next emits
 * inline bootstrap scripts without a nonce on prerendered pages, so inline is
 * allowed; what this buys is that nothing loads from, posts to or is framed by
