#!/usr/bin/env bun
/**
 * End-to-end probe of a deployed POC without email access. Adapted from
 * Permission Assist host/scripts/probe.ts.
 *
 *   APP_URL=https://<id>.poc.nicholaswood.com.au APP_ID=<id> FIREBASE_PROJECT_ID=<project> \
 *   NEXT_PUBLIC_FIREBASE_API_KEY=<key> bun run probe <allocated-email> <unallocated-email>
 *
 * Mints ID tokens through Firebase custom tokens (needs the caller to have
 * Firebase Auth admin, i.e. run it as the platform owner, not from CI).
 * Expects: signed-out refusals; the allocated user gets 200 with a self-only
 * CSP; the unallocated user gets 403 and no cookie. Exits non-zero on any FAIL.
 */
import { applicationDefault, initializeApp } from "firebase-admin/app";
import { getAuth } from "firebase-admin/auth";
import { externalOriginsIn } from "@lsv-poc/poc-auth";

const APP_URL = (process.env.APP_URL ?? "").replace(/\/$/, "");
const appId = process.env.APP_ID ?? "";
const apiKey = process.env.NEXT_PUBLIC_FIREBASE_API_KEY ?? "";
const [member, outsider] = process.argv.slice(2).map((s) => s.toLowerCase());
if (!APP_URL || !appId || !apiKey || !member || !outsider) throw new Error("APP_URL, APP_ID, NEXT_PUBLIC_FIREBASE_API_KEY, an allocated and an unallocated email are required");

initializeApp({ credential: applicationDefault(), projectId: process.env.FIREBASE_PROJECT_ID });
const auth = getAuth();
let failed = 0;
const check = (name: string, ok: boolean, detail = "") => {
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? `  [${detail}]` : ""}`);
};

async function idTokenFor(email: string) {
  const u = await auth.getUserByEmail(email).catch(() => null);
  if (!u) throw new Error(`${email} has no account; grant or create it in the hub first`);
  const ct = await auth.createCustomToken(u.uid);
  const r = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signInWithCustomToken?key=${apiKey}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Referer: `${APP_URL}/` },
    body: JSON.stringify({ token: ct, returnSecureToken: true }),
  });
  const b = (await r.json()) as { idToken?: string };
  if (!b.idToken) throw new Error("custom token exchange failed");
  return b.idToken;
}
const session = (idToken: string) => fetch(`${APP_URL}/api/auth/session`, { method: "POST", headers: { "Content-Type": "application/json", Origin: APP_URL }, body: JSON.stringify({ idToken }) });

console.log(`# Signed out: ${APP_URL}`);
for (const p of ["/", "/index.html", "/admin"]) {
  const r = await fetch(`${APP_URL}${p}`, { redirect: "manual" });
  check(`GET ${p} -> 303 to /sign-in`, r.status === 303 && (r.headers.get("location") ?? "").endsWith("/sign-in"), String(r.status));
}
check("GET /api/health -> 200", (await fetch(`${APP_URL}/api/health`)).status === 200);
check("GET /api/admin/settings -> 401", (await fetch(`${APP_URL}/api/admin/settings`)).status === 401);

console.log(`\n# Unallocated: ${outsider}`);
const o = await session(await idTokenFor(outsider));
check("POST /api/auth/session -> 403 and no cookie", o.status === 403 && !o.headers.get("set-cookie"), String(o.status));

console.log(`\n# Allocated: ${member}`);
const s = await session(await idTokenFor(member));
const cookie = (s.headers.get("set-cookie") ?? "").split(";")[0];
check("POST /api/auth/session -> 200 and __session", s.status === 200 && cookie.startsWith("__session="), String(s.status));
const page = await fetch(`${APP_URL}/`, { headers: { Cookie: cookie }, redirect: "manual" });
const csp = page.headers.get("content-security-policy") ?? "";
check("GET / -> 200 text/html", page.status === 200 && (page.headers.get("content-type") ?? "").startsWith("text/html"), String(page.status));
