import { describe, expect, test } from "bun:test";
import { readFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";
import { appClaimName, createAccessGate, roleFromClaims, signSession, SIGN_IN_CSP, SESSION_COOKIE_NAME } from "@lsv-poc/poc-auth";
import { nameFromEmail } from "../src/lib/deps";

const read = (p: string) => readFileSync(resolve(import.meta.dir, "..", p), "utf8");
const SECRET = "test-secret-that-is-definitely-32-chars-long!!";

