  test("the app's claim is poc_oss and only that grants a role", () => {
    expect(appClaimName("oss")).toBe("poc_oss");
    expect(roleFromClaims({ poc_oss: "member" }, "oss")).toBe("member");
    expect(roleFromClaims({ poc_oss: "admin" }, "oss")).toBe("admin");
    expect(roleFromClaims({ member: true, admin: true }, "oss")).toBeNull();
    expect(roleFromClaims({ poc_permissions: "admin" }, "oss")).toBeNull();
    expect(roleFromClaims({ poc_oss: "owner" }, "oss")).toBeNull();
  });

  test("the session cookie is the one Firebase Hosting forwards", () => {
    expect(SESSION_COOKIE_NAME).toBe("__session");
    expect(read("src/middleware.ts")).toContain('request.cookies.get("__session")');
  });

  test("this app never writes sign-in claims or holds an allow-list", () => {
    for (const f of ["src/lib/deps.ts", "src/app/api/auth/session/route.ts", "src/app/api/auth/firebase-token/route.ts", "scripts/seed.ts"]) {
      expect(read(f)).not.toContain("setCustomUserClaims");
      expect(read(f)).not.toMatch(/collection\(["']members["']\)/);
    }
    for (const gone of ["src/lib/members.ts", "src/lib/claims.ts", "src/app/api/members/route.ts", "scripts/resync-claims.ts"]) expect(existsSync(resolve(import.meta.dir, "..", gone))).toBe(false);
  });

  test("the token mint copies the role from the verified session, not the request", () => {
    const mint = read("src/app/api/auth/firebase-token/route.ts");
    expect(mint).toContain("createCustomToken(a.user.uid, { [APP_CLAIM]: a.user.role })");
    expect(mint).not.toMatch(/request\.json\(\)/);
  });

  test("rules read only the app-scoped claim and honour the hub's access record", () => {
    const rules = read("firestore.rules");
    expect(rules).toContain("request.auth.token.get('poc_oss', '')");
    expect(rules).not.toMatch(/token\.member\b|token\.admin\b/);
    expect(rules).toContain("platformAccess/$(request.auth.uid)");
    expect(rules).toContain("!exists(overridePath())");
    expect(rules).toMatch(/match \/platformAccess\/\{uid\} \{ allow read, write: if false; \}/);
    expect(rules).not.toContain("match /members/");
  });

  test("sign-in page policy is the platform's", () => {
    expect(read("next.config.ts")).toContain(`"${SIGN_IN_CSP}"`);
  });

  test("pages render per request and nothing uses the old path prefix", () => {
    expect(read("src/app/layout.tsx")).toContain('export const dynamic = "force-dynamic"');
    for (const f of ["next.config.ts", "src/middleware.ts", "src/app/route.ts", "src/bridge/bridge.ts", "oss/src/ux/build.py"]) expect(read(f)).not.toContain("/lsv/dailysummary");
    expect(read("oss/index.html")).toContain('<script src="/vendor/docx.min.js">');
  });

  test("display name fallback", () => {
    expect(nameFromEmail("nicholas.h.wood@example.com")).toBe("Nicholas H Wood");
    expect(nameFromEmail("sam@example.com")).toBe("Sam");
  });
});

describe("access gate (vendored poc-auth) as this app uses it", () => {
  const cookie = (role: "member" | "admin", app = "oss", iat = 1000) => signSession({ app, uid: "u1", email: "a@example.com", role }, SECRET, iat);
  const gateWith = (override: { role: "member" | "admin" | null; updatedAt: number } | null) =>
    createAccessGate({ appId: "oss", secret: () => SECRET, readOverride: async () => override, now: () => 2000 });

  test("a member session is admitted; a session for another app is not", async () => {
    expect((await gateWith(null).check(cookie("member"), "member")).ok).toBe(true);
    expect((await gateWith(null).check(cookie("member", "permissions"), "member")).status).toBe(401);
    expect((await gateWith(null).check(undefined, "member")).status).toBe(401);
  });
  test("a hub revoke newer than the session ends it; an older record does not", async () => {
    expect((await gateWith({ role: null, updatedAt: 1500 * 1000 }).check(cookie("member"), "member")).status).toBe(403);
    expect((await gateWith({ role: null, updatedAt: 500 * 1000 }).check(cookie("member"), "member")).ok).toBe(true);
  });
  test("a hub downgrade lowers an admin session to member", async () => {
    const g = gateWith({ role: "member", updatedAt: 1500 * 1000 });
    expect((await g.check(cookie("admin"), "admin")).status).toBe(403);
    expect((await g.check(cookie("admin"), "member")).ok).toBe(true);
  });
});
