cd /home/nicholas-wood/Documents/workspace/projects/lsv-service-summary/code && python3 -I - <<'EOF'
p='infra/modules/poc-app/monitoring.tf'; s=open(p).read()
i=s.index('  conditions {\n    display_name = "${var.app_id} job failures"'); j=s.index('  user_labels = local.labels', i)
new='''  # LOCAL PATCH (Service Summary, 22 Nov 2026): the job_failures metric covers
  # two monitored resource types, and an alert filter must name exactly one,
  # so the upstream single condition is rejected with "must specify a
  # restriction on resource.type". One condition per type, combined with OR.
  # Reported to the platform; drop this note when the fix is vendored.
  dynamic "conditions" {
    for_each = { host = "cloud_run_revision", scheduler = "cloud_scheduler_job" }
    content {
      display_name = "${var.app_id} job failures (${conditions.key})"
      condition_threshold {
        filter          = "metric.type=\\"logging.googleapis.com/user/${google_logging_metric.job_failures[0].name}\\" AND resource.type=\\"${conditions.value}\\""
        comparison      = "COMPARISON_GT"
        threshold_value = 0
        duration        = "0s"
        aggregations {
          alignment_period     = "300s"
          per_series_aligner   = "ALIGN_SUM"
          cross_series_reducer = "REDUCE_SUM"
        }
      }
    }
  }
'''
open(p,'w').write(s[:i]+new+s[j:])
EOF
