#!/usr/bin/env bun
/**
 * Read-only check of the Word export on the deployed app: signs in without
 * email, exports each report period, and prints the weather table text.
 *
 *   APP_URL=... NEXT_PUBLIC_FIREBASE_API_KEY=... bun run scripts/export-probe.ts <allocated-email> [outDir]
 *
 * Writes nothing to the shared data.
 */
import { mkdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { chromium } from "playwright";
import { APP_URL, check, cookieFrom, exchange, finish, idTokenForEmail } from "./lib-probe";

const email = process.argv[2];
const outDir = process.argv[3] ?? "/tmp/oss-export-probe";
if (!email) throw new Error("usage: export-probe <allocated-email> [outDir]");
mkdirSync(outDir, { recursive: true });
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

const cookie = decodeURIComponent(cookieFrom(await exchange((await idTokenForEmail(email)).idToken)).replace(/^__session=/, ""));
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1400, height: 900 }, acceptDownloads: true });
await context.addCookies([{ name: "__session", value: encodeURIComponent(cookie), url: APP_URL, httpOnly: true, secure: true, sameSite: "Lax" }]);
const page = await context.newPage();
const errors: string[] = [];
page.on("pageerror", (e) => errors.push(e.message));
try {
  await page.goto(`${APP_URL}/#report`, { waitUntil: "domcontentloaded" });
  for (let i = 0; i < 160 && !(await page.evaluate("Object.keys(S.units).length > 50 && Object.keys(S.weather).length > 0").catch(() => false)); i++) await sleep(250);
  const presets = (await page.evaluate("presets().map(p => p[1] + '|' + p[2])")) as string[];
  for (const pr of presets) {
    await page.click(`[data-preset="${pr}"]`);
    await sleep(700);
    const [dl] = await Promise.all([page.waitForEvent("download", { timeout: 60_000 }), page.click("#r-export")]);
    const path = join(outDir, dl.suggestedFilename());
    await dl.saveAs(path);
    const xml = await page.evaluate(
      async (b64) => {
        // JSZip is already on the page; read the document part back out of the file just produced.
        const zip = await (window as unknown as { JSZip: { loadAsync(d: string, o: object): Promise<{ file(n: string): { async(t: string): Promise<string> } }> } }).JSZip.loadAsync(b64, { base64: true });
        return zip.file("word/document.xml").async("string");
      },
      Buffer.from(await Bun.file(path).arrayBuffer()).toString("base64")
    );
    const text = xml.replace(/<\/w:tc>/g, " | ").replace(/<\/w:tr>/g, "\n").replace(/<[^>]+>/g, "").replace(/&amp;/g, "&");
    const wx = text.split("\n").filter((l) => /Min Temp|Max Temp|Wind \(KM\/h\)|Wind Direction|Rain \(mm\)|Max UV/.test(l));
    const emptyCells = wx.flatMap((l) => l.split("|").slice(2, -1)).filter((c) => c.trim() === "").length;
    const na = (text.match(/Not available/g) ?? []).length;
    console.log(`\n# ${dl.suggestedFilename()} (${statSync(path).size} bytes): ${wx.length} weather rows, ${na} "Not available", ${emptyCells} blank weather cells`);
    console.log(wx.slice(0, 6).map((l) => "  " + l.replace(/\s+/g, " ").trim()).join("\n"));
    check(`${dl.suggestedFilename().split(" Operational")[0]}: no blank weather cells`, wx.length >= 6 && emptyCells === 0, `${emptyCells} blank`);
    check(`${dl.suggestedFilename().split(" Operational")[0]}: unpublished figures read "Not available"`, na > 0, String(na));
  }
  check("no page errors", errors.length === 0, errors.slice(0, 2).join(" | "));
} finally {
  await browser.close();
}
finish();
EOF
