import xml.etree.ElementTree as ET
for f in ['IDZ00110','IDZ00112']:
    try:
        r=ET.parse(f+'.xml').getroot()
        print(f, 'title:', (r.findtext('.//product-type') or ''), '|', (r.findtext('.//title') or '')[:80])
        areas=[a for a in r.iter('area')]
