88	export function buildFeed(xml: { townPrecis: string; townText: string; metro: string; uv?: string }, fetchedAt = new Date()): BomFeed {
89	  const amoc = (product(xml.townPrecis).amoc ?? {}) as Node;
90	  const feed: BomFeed = {
91	    format: "lsv-bom-weather",
92	    version: 1,
93	    fetched: fetchedAt.toISOString(),
94	    issued: scalar(amoc["issue-time-local"]),
95	    towns: {},
96	  };
97	  collect(feed, xml.townPrecis, "location", "", PRECIS_KEYS, ["element", "text"]);
98	  // UV alert first, so a town's own text forecast (when it carries a UV line) still wins for that day.
99	  if (xml.uv) collect(feed, xml.uv, "location", "", { uv_alert: "uvText" }, ["text"]);
100	  collect(feed, xml.townText, "location", "", TEXT_KEYS, ["text"]);
101	  collect(feed, xml.metro, "metropolitan", "area:", TEXT_KEYS, ["text"]);
102	  return feed;
103	}
